// ══════════════ SUPERSETS ══════════════
// Deux exercices enchaînés sans repos doivent être visibles ENSEMBLE : les
// alterner série par série en naviguant d'un écran à l'autre est impraticable
// une barre en main.
//
// Modèle : un exercice porte « ss:true » = enchaîné avec le PRÉCÉDENT. Les
// groupes s'en déduisent, il n'y a pas d'identifiant à maintenir, et
// sessionData reste indexé par le vrai index de l'exercice : l'enregistrement
// par nom, l'historique et les charges suggérées ne changent pas d'un iota.
function _groupesEx(exercices){
  const g=[];
  (exercices||[]).forEach((ex,i)=>{
    // Le premier exercice ne peut pas être enchaîné avec un précédent qui
    // n'existe pas : on ouvre toujours un groupe sur lui.
    if(i===0||!ex||!ex.ss) g.push([i]); else g[g.length-1].push(i);
  });
  return g;
}
function _groupeDe(exercices,idx){
  return _groupesEx(exercices).find(g=>g.includes(idx))||[idx];
}
// Repère affiché : le NUMÉRO DU GROUPE, suffixé d'une lettre quand le groupe
// en contient plusieurs, comme « 3a / 3b » sur une fiche. Numéroter par groupe
// et non par exercice évite qu'un exercice seul placé après deux supersets
// s'affiche « 3 » alors qu'il est le cinquième de la liste.
const _SS_LETTRES='abcdefghijklmnopqrstuvwxyz';
function _repereEx(exercices,idx){
  const grs=_groupesEx(exercices);
  const gi=grs.findIndex(g=>g.includes(idx));
  if(gi<0) return String(idx+1);
  const g=grs[gi];
  if(g.length<2) return String(gi+1);
  return String(gi+1)+(_SS_LETTRES[g.indexOf(idx)]||'');
}
// Après une suppression ou un réordonnancement, un exercice peut se retrouver
// enchaîné avec un précédent qui n'est plus le bon, ou en tête de liste.
function _normaliserSS(exercices){
  (exercices||[]).forEach((ex,i)=>{ if(ex&&i===0) ex.ss=false; });
  return exercices;
}
function pad(n){return n.toString().padStart(2,'0');}
// PURE. La durée écoulée d'une séance, en secondes, mise en forme.
//
// ⚠ TOUJOURS hh:mm:ss, HEURE COMPRISE MEME A ZERO. Demande de Kevin,
// 15/09/2026 : « 00:00:00 heure minute seconde ». La version d'avant masquait
// l'heure sous les soixante minutes — « 04:32 » — pour ne pas faire payer aux
// séances courtes la longueur de la plus longue. Le prix de ce choix est
// qu'on ne sait pas, en voyant « 04:32 », si on lit 4 minutes ou 4 heures :
// deux champs qui changent de sens en cours de séance. Trois champs fixes
// coûtent trois caractères et ne mentent jamais.
//
// LARGEUR STABLE : chaque champ est sur deux chiffres, donc le chronomètre ne
// change plus de largeur en cours de séance — il ne fait plus sauter le titre
// à sa gauche à la première heure franchie.
//
// Elle existe parce que trois fonctions calculaient cet affichage à
// l'identique : corriger trois fois, c'est accepter qu'une quatrième copie
// naisse un jour et diverge.
function fmtDureeSeance(s){
  s=Math.max(0,Math.floor(Number(s)||0));
  const h=Math.floor(s/3600), m=Math.floor(s%3600/60), sec=s%60;
  return pad(h)+':'+pad(m)+':'+pad(sec);
}
// Un écran de séance affiche un GROUPE : un exercice seul, ou les deux (ou
// plus) d'un superset. Le corps propre à un exercice a été sorti dans
// _blocExo pour pouvoir en rendre plusieurs côte à côte ; tout ce qui vaut
// pour l'écran entier (échauffement, photo, encart RIR) reste ici, en un seul
// exemplaire.

// ── Guidage en séance ───────────────────────────────────────────────────────
// La bannière reprend la description du guide MOT POUR MOT, avec le lien vers
// la vidéo du coach. L'app n'explique pas la méthode à sa façon : elle affiche
// celle qui est déjà écrite et filmée.
//
// Le décompte est un CONFORT, jamais une condition : aucune saisie n'est
// bloquée parce qu'un compteur n'a pas été touché.
function banniereTechnique(ex,idx){
  const m=methodeDe(ex);
  const fam=techniqueDe(ex);
  if(!m||fam==='normale'&&!m) return '';
  const c=COUL_FAMILLE[fam]||['var(--border)','#bbb'];
  // Sur quelles séries la méthode s’applique. À CÔTÉ DU NOM : c’est la
  // première chose à savoir quand on la lit debout entre deux séries.
  const _msTxt=String((ex&&ex.methodeSeries)||'').trim();
  const compteur=(fam==='rest_pause'||fam==='myo_reps')?_compteurRelances(idx):'';
  // LA CONSIGNE D'EXECUTION, EN UNE PHRASE, ET AVANT LE RESTE. La
  // description du catalogue est un paragraphe : lu debout entre deux séries,
  // il n'est pas lu. Une méthode mal exécutée ne vaut pas mieux qu'une méthode
  // absente. Le paragraphe reste dessous — on ajoute, on ne retire rien.
  const _cons=(()=>{ try{ const r=regleMethode(ex,currentUser); return (r&&r.consigne)||''; }
                     catch(e){ return ''; } })();
  return `<div style="background:${c[0]}22;border:1px solid ${c[0]};border-radius:var(--r-3);padding:10px 14px;margin-bottom:12px;font-size:var(--fs-sm);line-height:1.6;color:var(--text-strong)">
    <strong style="color:${c[1]}">${escapeHtml(m.nom)}${m.sous?' ('+escapeHtml(m.sous)+')':''}${_msTxt?' · séries : '+escapeHtml(_msTxt):''} :</strong>
    ${_cons?`<div style="font-weight:700;color:var(--text);margin:4px 0 6px">${escapeHtml(_cons)}</div>`:''}
    ${escapeHtml(m.desc)}
    ${videoTechnique(m)?`<a href="${safeUrl(videoTechnique(m))}" target="_blank" rel="noopener" style="color:var(--link);white-space:nowrap"> · vidéo</a>`:''}
    ${compteur}
  </div>`;
}
// Décompte de repos entre deux relances. Une seule minuterie à la fois, et le
// même patron que le chronomètre de la checklist : il n'y avait aucune
// minuterie de repos dans l'écran de séance à réutiliser.
function _compteurRelances(idx){
  const d=woState&&woState.sessionData&&woState.sessionData[idx];
  const faites=(d&&d.relancesFaites)||0;
  return `<div style="display:flex;align-items:center;gap:10px;margin-top:10px;flex-wrap:wrap">
    <span style="font-size:var(--fs-xs);color:var(--sub)">Relances :</span>
    <span id="rel-n-${idx}" style="font-size:var(--fs-lg);font-weight:400;font-family:var(--pile-titre);letter-spacing:1px">${faites}</span>
    <button onclick="_ajouterRelance(${idx})" class="hit44" style="background:var(--surface-2);border:1px solid var(--border);border-radius:var(--r-2);color:var(--text);font-size:var(--fs-lg);font-weight:800;min-width:38px;min-height:34px;cursor:pointer">+</button>
    ${faites?`<button onclick="_retirerRelance(${idx})" class="hit44" style="background:none;border:1px solid var(--border);border-radius:var(--r-2);color:var(--sub);font-size:var(--fs-md);min-width:34px;min-height:34px;cursor:pointer">−</button>`:''}
  </div>`;
}
function _ajouterRelance(idx){
  if(!woState||!woState.sessionData||!woState.sessionData[idx]) return;
  const d=woState.sessionData[idx];
  d.relancesFaites=Math.min(99,((d.relancesFaites|0)||0)+1);
  demarrerRepos(REPOS_RELANCE,'relance');
  woPersist();
  const n=document.getElementById('rel-n-'+idx);
  if(n) n.textContent=d.relancesFaites;
}
function _retirerRelance(idx){
  const d=woState&&woState.sessionData&&woState.sessionData[idx];
  if(!d) return;
  d.relancesFaites=Math.max(0,((d.relancesFaites|0)||0)-1);
  woPersist();
  renderWoEx();
}
// Le décompte de relance passait par son propre setInterval et DÉCRÉMENTAIT
// un compteur : il dérivait dès que l'écran se verrouillait. Il est remplacé
// par le minuteur de repos, qui lit une échéance. Une seule mécanique.

