// Les six groupes que la face ne montre pas en premier : ils décident à eux
// seuls du retournement de la silhouette.
const WO_MUSCLES_DOS = Object.freeze(
  ['DORSAUX','LOMBAIRES','DELT_POST','TRICEPS','ISCHIOS','FESSIERS']);
// PURE. La vue à montrer : le dos SI TOUS les primaires sont dorsaux. Un
// exercice mixte reste de face — retourner la silhouette pour un muscle
// secondaire ferait perdre de vue le principal.
function woVueAvatar(muscles){
  const m=muscles||[];
  return (m.length && m.every(x=>WO_MUSCLES_DOS.includes(x))) ? 'dos' : 'face';
}

// PURE. Les muscles à allumer pour un exercice : ses PRIMAIRES, et eux seuls.
// Les secondaires reçoivent un stimulus réel mais moindre ; les peindre de la
// même couleur ferait lire « c'est là que ça travaille » sur la moitié du corps.
function woMusclesAvatar(ex,user){
  try{
    const cls=resoudreMusclesLecture(ex&&ex.name,ex,user||currentUser);
    return (cls&&cls.p)?cls.p.slice():[];
  }catch(e){ return []; }
}
// Le calque des zones. Vide s'il n'y a rien à montrer — de face, un exercice
// purement dorsal n'a aucune zone, et c'est assumé.
function woHtmlZones(muscles,src,vue,niv,genre){
  const par=((WO_ZONES[genre]||{})[vue]||{})[niv]||{};
  const f=[];
  (muscles||[]).forEach(m=>{
    (par[m]||[]).forEach(p=>{ f.push('<polygon points="'+p+'"/>'); });
  });
  if(!f.length) return '';
  // Le masque reste la vignette elle-même, ceinture et bretelles : le contour
  // est déjà déduit de CE dessin, mais un demi-pixel de débord au bord du bras
  // se verrait, et le masque le mange sans rien coûter.
  const mq="-webkit-mask-image:url('"+src+"');mask-image:url('"+src+"')";
  return '<svg class="wo-ava-z" viewBox="0 0 100 100" preserveAspectRatio="none"'
    +' aria-hidden="true" style="'+mq+'">'+f.join('')+'</svg>';
}

// ══ L'AVATAR DE PROGRESSION ═══════════════════════════════════════════════
// Sept niveaux découpés dans les planches fournies, un jeu par genre.
const WO_AVA_NIV=7;
// PURE. Le niveau pour un écran donné : 1 au premier, 7 au dernier.
// ON COMPTE LES ÉCRANS, PAS LES EXERCICES : un superset est un seul écran, et
// compter les exercices ferait sauter deux niveaux d'un coup au milieu d'un
// bloc — l'athlète verrait son bonhomme grossir sans avoir rien terminé.
function woNiveauAvatar(ecran,total){
  if(!(total>1)) return WO_AVA_NIV;
  const e=Math.max(0,Math.min(Number(ecran)||0,total-1));
  return 1+Math.round(e*(WO_AVA_NIV-1)/(total-1));
}
// LE GENRE SE LIT COMME PARTOUT AILLEURS : _evol_gender d'abord, .gender
// ensuite, et isFemale pour trancher. Cette fonction lisait `.gender` seul et
// le comparait à 'F' — d'où une athlète femme devant un bonhomme masculin,
// signalé par Kevin le 25/08/2026. Trois cas sur quatre tombaient à côté :
//   • `_evol_gender:'F'` sans .gender — c'est le cas COURANT. _evol_gender
//     n'existe qu'à partir du premier bilan ; une athlète créée par son coach
//     porte son sexe là et nulle part ailleurs.
//   • `_evol_gender:'F'` avec .gender vide — même chose, chaîne vide.
//   • `.gender:'femme'` — une convention historique du dépôt, qu'isFemale
//     absorbe déjà et que le test à 'F' ratait.
// Le même piège avait été relevé et corrigé côté coach (voir la Fondation et
// _coachEditClient) ; l'avatar de séance était resté en arrière.
// LES 28 PLANCHES EXISTENT DEPUIS TOUJOURS — 7 niveaux × h/f × face/dos — et
// WO_ZONES porte les contours musculaires des deux. Il n'y avait rien à
// dessiner : seulement à choisir la bonne.
function woGenreAvatar(u){
  return isFemale(u&&(u._evol_gender||u.gender)) ? 'f' : 'h';
}
function woSrcAvatar(niv,genre,vue){
  return './icons/avatar/n'+niv+'-'+genre+(vue==='dos'?'-dos':'')+'.png';
}
// LES SEPT IMAGES SONT PRÉCHARGÉES au montage de la séance. Sans cela le
// changement de niveau laisserait un trou le temps du téléchargement — et hors
// ligne un trou définitif, le service worker ne mettant en cache que ce qu'il a
// vu passer. Sept fichiers de neuf kilo-octets.
let _woAvaPrecharge=null;
function woPrechargerAvatars(){
  const g=woGenreAvatar(currentUser);
  if(_woAvaPrecharge===g) return;
  _woAvaPrecharge=g;
  // LES DEUX VUES. Un exercice dorsal peut tomber n'importe où dans la séance,
  // et la planche de dos manquerait au moment précis où on en a besoin.
  for(let n=1;n<=WO_AVA_NIV;n++){
    for(const v of ['face','dos']){ const i=new Image(); i.src=woSrcAvatar(n,g,v); }
  }
}
// Pose l'avatar dans la PREMIÈRE carte de l'écran et retire les autres : un
// superset en rend plusieurs, et sept bonshommes empilés ne diraient rien.
function woMajAvatar(ecran,total,ex){
  const zones=document.querySelectorAll('.wo-ava');
  if(!zones.length) return;
  for(let k=1;k<zones.length;k++) zones[k].remove();
  const z=zones[0];
  const niv=woNiveauAvatar(ecran,total), g=woGenreAvatar(currentUser);
  const mus=woMusclesAvatar(ex,currentUser);
  const vue=woVueAvatar(mus);
  const src=woSrcAvatar(niv,g,vue);
  z.innerHTML='<img class="wo-ava-img" alt="" aria-hidden="true" src="'+src+'">'
    +woHtmlZones(mus,src,vue,niv,g);
  z.dataset.niveau=String(niv);
  z.dataset.vue=vue;
}
// Les compteurs et la barre, mis à jour APRÈS l'écriture du contenu : ils
// vivent désormais DANS la carte de l'exercice, et n'existent donc pas avant.
let _woCptPrec=NaN;
function woMajProgression(gi,grs){
  // ── ANIMATION 5 : LE COURANT MONTE DANS LA BARRE ────────────────────────
  // --arc-pc et non style.width : la barre est mise à l'échelle par un
  // transform, qui ne relance jamais la mise en page. Voir .progress-fill.
  const _barre=document.getElementById('wo-progress');
  const _avantPc=parseFloat(_barre.style.getPropertyValue('--arc-pc'))||0;
  const _pc=grs.length?gi/grs.length:0;
  _barre.style.setProperty('--arc-pc',_pc.toFixed(4));
  // Le courant PASSE dans le segment gagné, il ne s'y allume pas. Seulement
  // quand la barre avance : revenir en arrière n'est pas une progression, et
  // la célébrer brouillerait le signal.
  if(_pc>_avantPc){
    try{ arcTraversee(_barre.parentElement,{duree:ARC.release}); }catch(e){}
  }
  // Le compteur suit les ÉCRANS, pas les exercices : un superset est un seul
  // écran. Le nombre d'exercices reste visible sur le badge de chaque bloc.
  // Le CHIFFRE s'anime aussi, pas seulement la barre — d'où l'interpolation
  // depuis la valeur affichée. tabular-nums est posé sur l'élément : sans lui,
  // le passage de 1 à 4 change la largeur du texte et fait sauter la barre qui
  // le précède, à chaque frame.
  const _cpt=document.getElementById('wo-ex-count');
  // LA VALEUR PRÉCÉDENTE VIENT D'UNE VARIABLE, plus du texte affiché : celui-ci
  // est détruit à chaque rendu depuis que le compteur vit dans la carte.
  const _avantN=_woCptPrec;
  _cpt.style.fontVariantNumeric='tabular-nums';
  _woCptPrec=gi+1;
  arcChiffre(_cpt,isNaN(_avantN)?gi+1:_avantN,gi+1,
    {duree:ARC.strike,format:v=>Math.round(v)+'/'+grs.length});
  woMajCompteurSeries();
}
// LES SERIES DE TOUTE LA SEANCE, pas seulement de l'exercice courant : c'est
// la question qu'on se pose entre deux series — « il m'en reste combien ».
// PAS d'arcChiffre ici : ce compteur ne saute pas d'un exercice a l'autre,
// il avance d'une unite, et l'animer le rendrait moins lisible qu'immobile.
// ⚠ SA PROPRE FONCTION (30/09/2026) : il n'etait mis a jour que par
//   renderWoEx, donc au changement d'exercice. Valider une serie laissait
//   « 0/20 » a l'ecran jusqu'a « Suivant ». toggleSet, ajouterSerie et
//   retirerSerie l'appellent, sans toucher a la barre d'exercice.
// PURE. {fait, total} des series de la seance.
function comptesSeriesSeance(st){
  let fait=0,total=0;
  const sd=(st&&st.sessionData)||{};
  const sx=(st&&st.exercises)||[];
  for(let k=0;k<sx.length;k++){
    const l=(sd[k]&&sd[k].sets)||null;
    if(l){ total+=l.length; fait+=l.filter(x=>x&&x.done).length; }
    else { const n=parseInt(sx[k]&&sx[k].series,10); total+=isFinite(n)&&n>0?n:0; }
  }
  return {fait,total};
}
function woMajCompteurSeries(){
  try{
    // LE TOTAL SE COMPTE SUR LE PROGRAMME, PAS SUR sessionData. Ce dernier ne
    // se remplit qu'à l'OUVERTURE de chaque exercice : en parcourant ses seules
    // clés, le dénominateur ne comptait que le chemin déjà fait et grossissait
    // à mesure qu'on avançait — « 1/10 » sur une séance qui en compte 26. Le
    // défaut existait avant ; il devient voyant maintenant que le compteur est
    // dans la carte, à côté de ce qu'il compte.
    // sessionData reste PRIORITAIRE quand il existe : c'est lui qui porte les
    // séries ajoutées ou retirées à la main pendant la séance.
    const _c=comptesSeriesSeance(woState), _sFait=_c.fait, _sTot=_c.total;
    const _sc=document.getElementById('wo-set-count');
    if(_sc) _sc.textContent=_sTot?(_sFait+'/'+_sTot+' séries'):'';
  }catch(e){}
}
function renderWoEx(){
  const total=woState.exercises.length;
  const grs=_groupesEx(woState.exercises);
  let gi=grs.findIndex(g=>g.includes(woState.currentEx));
  if(gi<0) gi=0;
  const groupe=grs[gi];
  // Une reprise de séance enregistrée avant les supersets peut pointer au
  // milieu d'un groupe : on se recale sur sa tête.
  woState.currentEx=groupe[0];
  const estSS=groupe.length>1;

  document.getElementById('wo-prev-btn').style.opacity=gi===0?'0.3':'1';
  // innerHTML et non textContent : les deux libellés (long/court) doivent
  // survivre au changement d'exercice, sinon la version mobile disparaît dès le
  // premier woNav et le texte se remet à déborder.
  document.getElementById('wo-next-btn').innerHTML=gi===grs.length-1
    ?'<span class="wo-lbl-long">Terminer la séance</span><span class="wo-lbl-court">Terminer</span> '
    :'<span class="wo-lbl-long">Exercice suivant</span><span class="wo-lbl-court">Suivant</span> →';

  // Photo programme en haut si disponible
  const photoHtml=woState.sessionPhoto?`<div style="margin-bottom:14px;border-radius:var(--r-3);overflow:hidden;border:1px solid var(--border)">
    <div style="font-size:var(--fs-xs);color:var(--sub);padding:6px 10px;background:var(--surface-2)"> Ta fiche programme (référence)</div>
    <img src="${srcImageAttr(woState.sessionPhoto)}" style="width:100%;max-height:160px;object-fit:cover;cursor:pointer" onclick="this.style.maxHeight=this.style.maxHeight==='none'?'160px':'none'" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}">
  </div>`:'';

  const blocs=groupe.map(i=>_blocExo(i,estSS));
  // R10 — voir _woTeteDeGroupe : en superset, seul le premier bloc porte les ⓘ.
  const auMoinsUnMuscu=groupe.some(i=>!isCardio(woState.exercises[i]));

  // SANS anim-in : le fondu vertical de 320 ms recouvrait entierement le
  // glissement horizontal de _arcGlissement. L'athlete voyait un contenu qui
  // apparait en montant, pas un contenu qui arrive par le cote. La classe
  // reste employee par cinq autres ecrans, elle n'est pas touchee ailleurs.
  // L'avatar se pose APRÈS l'écriture du contenu : c'est elle qui crée sa zone.
  // (appel en fin de fonction)
  document.getElementById('wo-content').innerHTML=`
    <div>
      ${(()=>{ try{ return htmlRepriseSeance(currentUser); }catch(e){ return ''; } })()}
      ${(()=>{ try{ return _htmlSelecteurSalle(); }catch(e){ return ''; } })()}
      ${woState.deload?`<div style="display:flex;align-items:center;gap:10px;background:var(--info-bg);border:1px solid var(--info-border);border-radius:var(--r-3);padding:10px 14px;margin-bottom:12px">
        <span style="font-size:var(--fs-xs);font-weight:800;letter-spacing:1.5px;color:var(--info);flex-shrink:0">DÉCHARGE</span>
        <span style="font-size:var(--fs-xs);color:#bbb;line-height:1.5">${woState.repriseDouce?'Reprise en douceur : tes charges proposées sont 10 % plus légères. Elle ne comptera pas comme un recul.':(woState.dechargePar==='athlete'?'Tu as allégé ta semaine. Elle ne comptera pas comme un recul.'
          :woState.dechargePar==='reprise'?'Semaine allégée pour ta reprise. Elle ne comptera pas comme un recul.'
          :'Semaine allégée voulue par ton coach. Elle ne comptera pas comme un recul.')}</span>
      </div>`:''}
      ${''/* « RECORD À PORTÉE » RETIRÉ DE LA TÊTE DE SÉANCE (Kevin, 29/09/2026) : l'éclair sur la série et le rappel restent. */}
      ${woState.currentEx===0?_carteProtocole(woState.warmup,'Échauffement','var(--orange)','wo-warmup-body',true,
        (()=>{ try{ return chargeReferenceEchauffement(0); }catch(e){ return null; } })()):''}
      ${photoHtml}
      ${estSS?`<div style="display:flex;align-items:center;gap:10px;background:#1a0f00;border:1px solid var(--orange);border-radius:var(--r-3);padding:10px 14px;margin-bottom:12px">
        <svg viewBox="0 0 24 24" fill="none" stroke="var(--orange)" stroke-width="1.75" stroke-linecap="square" stroke-linejoin="miter" width="17" height="17" style="flex-shrink:0"><path d="M17 2l4 4-4 4"/><path d="M3 11V9a4 4 0 0 1 4-4h14"/><path d="M7 22l-4-4 4-4"/><path d="M21 13v2a4 4 0 0 1-4 4H3"/></svg>
        <div style="flex:1;min-width:0">
          <div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:2px;color:var(--orange)">SUPERSET</div>
          <div style="font-size:var(--fs-xs);color:#bbb;margin-top:2px;line-height:1.5">Enchaîne les ${groupe.length===2?'deux':groupe.length} exercices sans repos, puis repose-toi avant la série suivante.</div>
        </div>
      </div>`:''}
      ${blocs.map(b=>b.html).join(estSS?`<div style="display:flex;align-items:center;gap:8px;margin:2px 0 12px"><div style="flex:1;height:1px;background:var(--orange);opacity:.35"></div><span style="font-size:var(--fs-xs);color:var(--orange);letter-spacing:1.5px;font-weight:800">PUIS ENCHAÎNER</span><div style="flex:1;height:1px;background:var(--orange);opacity:.35"></div></div>`:'')}
      ${auMoinsUnMuscu?`<div style="margin-top:10px">
        <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px">
          <!-- La règle globale « label » met en majuscules et espace les lettres :
               « FILMER CET EXERCICE » débordait alors sur deux lignes dès qu'un
               écran étroit la mettait en concurrence avec le rappel RIR. C'est
               une phrase, pas un intitulé de champ. -->
          <label class="hit44" style="font-size:var(--fs-xs);cursor:pointer;color:var(--sub);text-transform:none;letter-spacing:normal;font-weight:400;margin:0;display:inline-flex;align-items:center;gap:6px"><input type="checkbox" id="film-ex" style="width:auto;margin:0">Filmer cet exercice</label>
          <!-- R11, LE PANNEAU « ? » DU RIR A ETE RETIRE (Kevin, 17/09/2026 :
               « laisse le RIR, que dans le tableau, la def »).
               R23, ET LE RAPPEL DE CONSIGNE RIR 0 DE BAS D'ECRAN AUSSI,
               apres verification : RC_LEXIQUE.rir.p porte ce conseil (« Vise
               RIR 2 sur tes premières séries, RIR 0 à 1 sur la dernière. »),
               a un doigt dans l'en-tete RIR du tableau. La case « Filmer cet
               exercice » reste : c'est une action, pas une explication. -->

        </div>
      </div>`:''}
      ${(()=>{ try{ return _carteCalibrageRir(groupe,gi===grs.length-1); }catch(e){ return ''; } })()}
    </div>`;

  // Handlers posés en JS, hors attribut. Auparavant les trois valeurs etaient
  // interpolees DANS onclick : cela ne cassait pas — JSON.stringify les met
  // entre guillemets doubles avant qu'escapeHtml n'encode l'apostrophe, donc
  // « 10 par bras d'appui » passait — mais la correction ne tenait qu'a l'ordre
  // de ces deux appels. Retirer le JSON.stringify, ou echapper apres, suffisait
  // a produire du JS invalide dans un attribut. Ici, plus rien n'est parse
  // comme du code : les valeurs restent des valeurs.
  blocs.forEach(b=>{
    const cb=document.getElementById('wo-calc-btn-'+b.idx);
    if(cb) cb.onclick=()=>openCalc(b.sug,b.ex.reps,'0',currentUser.gender);
    renderSets(b.ex,b.data,b.idx);
  });
  // La case « Filmer cet exercice » n'était qu'un décor : elle ne se relisait
  // nulle part et repartait vierge à chaque changement d'exercice. Son état
  // vient maintenant de woState.aFilmer et y retourne.
  const _film=document.getElementById('film-ex');
  if(_film){
    const _nomsF=_nomsAFilmer(groupe);
    _film.checked=_nomsF.length>0&&_nomsF.every(estAFilmer);
    _film.onchange=function(){ basculerAFilmer(this.checked,groupe); };
  }
  // L'AVATAR SE POSE ICI, et pas plus haut : sa zone n'existe qu'une fois le
  // contenu écrit. Le préchargement, lui, est idempotent — il ne refait rien
  // tant que le genre n'a pas changé.
  // Les deux vivent dans la carte : ils se posent APRÈS son écriture. Un
  // superset en rend plusieurs, on ne garde que la première.
  try{
    const _p=document.querySelectorAll('.wo-prog');
    for(let k=1;k<_p.length;k++) _p[k].remove();
    woMajProgression(gi,grs);
  }catch(e){}
  // L'exercice de tête du groupe donne les muscles : sur un superset, c'est lui
  // qui ouvre l'écran, et deux jeux de zones superposés ne désigneraient rien.
  try{ woPrechargerAvatars();
       woMajAvatar(gi,grs.length,(woState.exercises||[])[groupe[0]]); }catch(e){}
  woPersist();
  setTimeout(()=>blocs.forEach(b=>setupScrollFade(document.getElementById('wo-sets-scroll-'+b.idx))),0);
  // R15 — L'INDEX DES ILLUSTRATIONS, S'IL N'EST PAS ENCORE LA. Seule la zone
  // de consigne est repeinte a son arrivee : le tableau des series, avec ce
  // qu'on est peut-etre en train d'y taper, n'est pas touche. Un echec reseau
  // ne memorise rien, le prochain rendu retentera (chargerIndexIllustrations).
  if(!_exoIndex){
    const _g=groupe.slice();
    chargerIndexIllustrations().then(m=>{
      if(!m||!m.size) return;
      for(const i of _g){
        const z=document.getElementById('wo-consigne-'+i);
        const ex=woState&&woState.exercises&&woState.exercises[i];
        if(z&&ex) z.innerHTML=_htmlConsigneExo(ex);
        // R23 — le <details> qui l'enveloppe devient visible s'il a enfin
        // quelque chose a montrer. Son etat ouvert/replie n'est pas touche.
        const d=document.getElementById('wo-comment-'+i);
        if(d&&z) d.hidden=!(z.innerHTML.trim()||d.dataset.video==='1');
      }
    }).catch(()=>{});
  }
}

// ══ R15 — LA CONSIGNE D'UN EXERCICE, EN UN SEUL ENDROIT ════════════════
// Rendue par _blocExo, et REPEINTE par renderWoEx quand l'index des
// illustrations arrive apres le premier rendu.
//
// ⚠ POURQUOI ELLE DISPARAISSAIT. L'index n'etait charge que par l'apercu de
// seance et la banque du coach. Une seance ouverte autrement, et surtout une
// seance REPRISE — ce qui arrive a chaque mise a jour de l'app, qui recharge
// la page — rendait sans index : pas d'image, et pour un exercice sans texte,
// plus de bloc CONSIGNE du tout. Rien ne repeignait ensuite.
function _htmlConsigneExo(ex){
  if(!ex) return '';
  const img=(()=>{ try{ return illustrationExo(ex); }catch(e){ return null; } })();
  if(!(ex.description||ex.materiel||ex.tempo||ex.reglageCoach||img)) return '';
  return `<div style="background:var(--surface-2);border-radius:var(--r-3);padding:12px 14px;margin-bottom:12px">
        <div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:1.5px;color:var(--red-text);margin-bottom:6px">CONSIGNE</div>
        ${blocTempo(ex)}
        <!-- LE MATÉRIEL EN PREMIER : c'est ce qu'on va chercher avant de
             commencer, pas ce qu'on lit pendant. Il fait aussi partie de la
             condition d'affichage du bloc, sans ça, un exercice qui ne
             porterait QUE son matériel n'aurait rien affiché du tout. -->
        ${ex.materiel?`<div style="font-size:var(--fs-xs);color:var(--sub);line-height:1.6;margin-bottom:6px"><span style="font-weight:800;letter-spacing:.5px">Matériel :</span> ${escapeHtml(ex.materiel)}</div>`:''}
        ${ex.reglageCoach?`<div class="ex-reglage" style="font-size:var(--fs-xs);color:var(--text);line-height:1.6;margin-bottom:6px"><span style="font-weight:800;letter-spacing:.5px;color:var(--red-text)">Réglage du coach :</span> ${escapeHtml(ex.reglageCoach)}</div>`:''}
        <div style="display:flex;gap:12px;align-items:flex-start">
          ${_htmlVignetteExo(ex)}
          <div style="flex:1;min-width:0;font-size:var(--fs-sm);color:#bbb;line-height:1.6">${escapeHtml(ex.description||'')}</div>
        </div>
      </div>`;
}
// R15 — LA VIDEO DU GUIDE QUAND LE PROGRAMME N'EN PORTE PAS. videosExo rend la
// video posee par le coach d'abord, puis celle du guide (par slug, puis par
// nom) : c'est deja ce que montrent l'apercu et la vue programme. La seance,
// elle, ne lisait que ex.videoUrl, et un exercice du guide sans lien recopie
// n'y avait plus de video.
// R23 — sortie de _blocExo : elle vit dans « Comment l'exécuter ».
// LA VIDEO GARDEE POUR CETTE SERIE (30/09/2026) : filmee pendant la seance,
// elle attend dans la file du telephone et part a la fin. Le badge dit
// qu'elle existe ; il ne dit pas qu'elle est partie.
function _badgeVideoSerie(s){
  return (s&&s.video)?'<span class="wo-vid-badge" role="img" aria-label="Une vidéo gardée pour cette série, envoi à la fin de la séance">'+icon('video',12)+' 1</span>':'';
}
function _htmlVideoTechniqueExo(ex){
  let u='';
  try{ const v=videosExo(ex).find(x=>x&&!x.methode); u=v?normaliserUrlVideo(v.url):''; }catch(e){ u=''; }
  if(!u) return '';
  let cle=''; try{ cle=exKey((ex&&ex.name)||'')||''; }catch(e){ cle=''; }
  if(cle) _demoExos[cle]=ex;
  // ⚠ PLUS DE target="_blank" (30/09/2026) : en pleine seance, la video
  //   ouvrait un onglet ou l'application YouTube, et l'athlete perdait son
  //   ecran de seance. Elle s'ouvre dans une feuille basse de l'app ; le href
  //   reste, pour le clic milieu et les lecteurs d'ecran.
  return u?`<a href="${safeUrl(u)}" data-demo="${escapeHtml(cle)}" onclick="return _videoDemoOuvrir(this,event)" style="display:flex;align-items:center;gap:12px;background:#08081a;border:1px solid #2a2a5a;border-radius:var(--r-3);padding:12px 14px;margin-bottom:12px;text-decoration:none;color:#7799ff">
        <div style="width:32px;height:32px;background:#1a1a3a;border-radius:var(--r-full);display:flex;align-items:center;justify-content:center;font-size:var(--fs-md);flex-shrink:0">▶</div>
        <div style="flex:1">
          <div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:.5px;color:#99aaff">VIDÉO TECHNIQUE</div>
          <div style="font-size:var(--fs-xs);color:var(--link);margin-top:2px">Regarder la technique d'exécution</div>
        </div>
        <span style="font-size:var(--fs-md);color:var(--link)">→</span>
      </a>`:'';
}
// ══ LA VIDEO DE DEMONSTRATION, DANS L'APP (30/09/2026) ═════════════════
// Une feuille basse, par-dessus la seance : on regarde, on ferme, on est
// toujours sur sa serie. YouTube passe par youtube-nocookie.com (aucun cookie
// tant que la lecture n'a pas commence) avec playsinline=1 : sur iPhone, sans
// lui, la lecture bascule en plein ecran natif.
//
// HORS LIGNE, l'iframe resterait un rectangle noir : on le dit, et on garde
// l'illustration de l'exercice, qui, elle, est en cache.
const _demoExos={};
/** PURE. L'identifiant YouTube d'une adresse, ou ''. */
function idYoutube(url){
  const m=String(url||'').match(/(?:youtube(?:-nocookie)?\.com\/(?:watch\?(?:.*&)?v=|embed\/|shorts\/|live\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/);
  return m?m[1]:'';
}
/** PURE. Le contenu de la feuille : lecteur, ou message hors connexion. */
function htmlFeuilleDemo(url,ex,enLigne){
  const titre=escapeHtml(String((ex&&ex.name)||'Vidéo technique'));
  let corps;
  if(enLigne===false){
    let ill=''; try{ ill=ex?_htmlVignetteExo(ex):''; }catch(e){ ill=''; }
    corps='<div class="demo-horsligne">Vidéo indisponible hors connexion</div>'
      +(ill?'<div class="demo-ill">'+ill+'</div>':'');
  } else {
    const id=idYoutube(url);
    corps=id
      ?'<div class="demo-cadre"><iframe src="https://www.youtube-nocookie.com/embed/'+id+'?playsinline=1" title="'+titre+'"'
        +' allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div>'
      :'<video class="demo-video" src="'+escapeHtml(safeUrl(url))+'" controls playsinline webkit-playsinline preload="metadata"></video>';
  }
  return '<div class="demo-poignee" aria-hidden="true"></div>'
    +'<div class="demo-tete"><div class="demo-titre">'+titre+'</div>'
    +'<button type="button" class="demo-fermer" onclick="_videoDemoFermer()" aria-label="Fermer la vidéo">'+icon('croix',14)+'</button></div>'
    +corps;
}
function _videoDemoOuvrir(a,e){
  const url=a&&a.getAttribute('href');
  if(!url) return true;
  // Ni YouTube, ni fichier video : rien a mettre dans un lecteur. On ouvre
  // l'adresse a part plutot que de quitter la seance.
  if(!idYoutube(url)&&!/\.(mp4|mov|webm|m4v)(\?|$)/i.test(url)){
    try{ window.open(url,'_blank','noopener'); }catch(x){}
    if(e) e.preventDefault(); return false;
  }
  if(e) e.preventDefault();
  _videoDemoFermer();
  const ex=_demoExos[(a.getAttribute('data-demo')||'')]||null;
  const voile=document.createElement('div');
  voile.id='rc-demo-voile'; voile.className='demo-voile';
  voile.onclick=_videoDemoFermer;
  const f=document.createElement('div');
  f.id='rc-demo'; f.className='demo-feuille';
  f.setAttribute('role','dialog'); f.setAttribute('aria-modal','true');
  f.setAttribute('aria-label',(ex&&ex.name)?'Vidéo technique : '+ex.name:'Vidéo technique');
  f.innerHTML=htmlFeuilleDemo(url,ex,navigator.onLine!==false);
  document.body.appendChild(voile);
  document.body.appendChild(f);
  _demoRetour=a;
  try{ f.querySelector('.demo-fermer').focus(); }catch(x){}
  return false;
}
let _demoRetour=null;
function _videoDemoFermer(){
  const f=document.getElementById('rc-demo'), v=document.getElementById('rc-demo-voile');
  // L'iframe part avec la feuille : la lecture s'arrete, le son aussi.
  if(f) f.remove(); if(v) v.remove();
  const r=_demoRetour; _demoRetour=null;
  if(r&&r.isConnected&&f) try{ r.focus({preventScroll:true}); }catch(x){}
  return true;
}
document.addEventListener('keydown',e=>{ if(e.key==='Escape'&&document.getElementById('rc-demo')){ e.preventDefault(); _videoDemoFermer(); } });
// ══ R23 — « COMMENT L'EXECUTER » EST-IL OUVERT ? ═══════════════════════
// PURE. Ouvert tant que l'athlete n'a JAMAIS valide de serie sur cet
// exercice : ni dans l'historique que la carte lit deja (getPrevPerf rend null
// sans antecedent), ni dans la seance en cours. Aucun stockage neuf.
//
// ET OUVERT EN PERMANENCE, quel que soit l'historique, quand quelque chose a
// change et doit etre lu :
//   • le coach demande une video de cet exercice ;
//   • une contrainte est active sur cet exercice ;
//   • l'exercice vient d'etre remplace pendant cette seance.
function _consigneOuverte(ex,data,prev,sig){
  sig=sig||{};
  if(sig.demandeVideo||sig.contrainte) return true;
  try{
    const k=exKey(ex&&ex.name);
    if((woState&&woState.substitutions||[]).some(s=>s&&exKey(s.vers)===k)) return true;
  }catch(e){}
  const dejaFait=!!prev||((data&&data.sets)||[]).some(s=>s&&s.done);
  return !dejaFait;
}
// Corps d'un seul exercice. Rend le HTML et renvoie de quoi câbler la suite :
// l'index est explicite partout, car deux exercices peuvent être à l'écran en
// même temps et woState.currentEx ne désigne alors que la tête du groupe.
function _blocExo(idx,estSS){
  const ex=woState.exercises[idx];
  const pr=parseReps(ex.reps);
  if(!woState.sessionData[idx]) woState.sessionData[idx]={sets:Array.from({length:ex.series},(_,si)=>({weight:'',weight2:'',reps:pr.type==='degressive'?pr.p1:ex.reps,rir:'',pain:'',done:false,degressive:pr.type==='degressive',p2reps:pr.p2}))};
  const data=woState.sessionData[idx];
  // ══ LA PROGRAMMATION DU COACH, SI ELLE EST ACTIVE CETTE SEMAINE ══════
  //
  // Elle donne trois choses d'un coup : le nombre de series, celui de
  // repetitions, et la charge — calculee depuis le 1RM et la table de
  // pourcentages. C'est la consigne, elle remplace le champ RIR par le RPE
  // demande, et l'athlete ne la modifie pas.
  //
  // LA CHARGE, ELLE, RESTE MODIFIABLE. C'est une SUGGESTION : la barre du
  // jour, la fatigue, une blessure naissante — l'athlete est le seul a
  // savoir. On pre-remplit, on ne verrouille pas.
  const _cons=(()=>{ try{ return consigneProgEx(ex,null,currentUser); }
                     catch(e){ return null; } })();
  if(_cons){
    // LES SERIES SUIVENT LA CONSIGNE. On AJOUTE ce qui manque et on ne retire
    // jamais une serie deja faite : une seance commencee ne se raccourcit pas
    // sous les pieds de celui qui la fait.
    while(data.sets.length<_cons.series)
      data.sets.push({weight:'',weight2:'',reps:_cons.reps,rir:'',pain:'',done:false});
    for(const s of data.sets){
      if(s.done) continue;
      s.reps=_cons.reps;
      // LE RPE DEMANDE EST POSE SUR LA SERIE, et il est bien distinct de
      // `rir` : `rir` est ce que l'ATHLETE a ressenti, `rpeCible` ce que le
      // coach a DEMANDE. Les confondre ferait passer une prescription pour
      // une mesure — et rirMoyenSeance, l'e1RM et l'ecart prescrit/realise
      // liraient tous une valeur que personne n'a constatee.
      s.rpeCible=_cons.rpe;
      if(_cons.kg!=null&&!s.userEdited&&!String(s.weight||'').trim()){
        s.weight=_cons.kg; s.isAuto=true;
      }
    }
  }
  const prev=getPrevPerf(ex.name,woState.slot,woState.progName);
  const cycle=getCycleFactor();
  const cycleLabel=getCycleLabel();
  // Calcul charge suggérée = last 0-RIR weight de la séance précédente
  // Contrepoids (DIPS/TRACTIONS assistés|guidés) : progression = MOINS de charge
  const isCW=isCounterweightEx(ex.name);
  // Nommer d'où vient la suggestion : c'est ce qui rend vérifiable le fait
  // qu'elle ne vient plus d'un autre jour de la semaine. Deux formulations,
  // parce que sans créneau connu il ne reste que le nom de la séance, et
  // « ton dernier SÉANCE 1 : DOS » ne se dit pas.
  const _jour=(woState.slot!=null&&DAYS[woState.slot])?DAYS[woState.slot].toLowerCase():null;
  const creneauRef=_jour?('ton dernier '+_jour):'ta séance précédente';
  const creneauPhrase=_jour?('le '+_jour):'sur cette séance';
  // La charge part TOUJOURS de la dernière série faite sur ce créneau, à
  // laquelle on applique le multiplicateur de son RIR. getLastZeroRIRWeight
  // n'est plus prioritaire : elle renvoyait la dernière charge notée à RIR 0,
  // parfois vieille de plusieurs séances, ce qui court-circuitait la
  // progression. Elle reste utilisée pour formuler l'explication.
  // Reprise après coupure. Sans _refDate — ancienne signature, ou séance sans
  // date — on ne décote rien et le comportement reste l'actuel.
  const _joursRef=prev?joursDepuisRef(prev._refDate):null;
  let _decote=_joursRef==null?1:decoteReprise(_joursRef);
  // La reprise en douceur acceptée : -10 %, sans cumuler avec la décote de
  // reprise — la plus forte des deux.
  if(woState.repriseDouce&&_decote!=null) _decote=Math.min(_decote,REPRISE_DOUCE_FACTEUR);
  const _abandon=!!prev&&_decote===null;
  const _rawSug=(prev&&!_abandon)?chargeSuivante(prev.weight,prev.rir,isCW,_decote,ex.name):null;
  const _sugBrut=_rawSug!=null&&_rawSug>0?_rawSug:null;
  // AU POIDS DU CORPS SANS LEST (typeCharge) : on progresse en répétitions.
  // +1 quand la dernière série laissait plus de réserve que le RIR visé.
  const _prevPdc=(!prev&&typeCharge(_exPourCharge(ex.name,currentUser))==='poids_corps')?_prevSeriePoidsCorps(ex.name,woState.slot,woState.progName):null;
  const _sugReps=_prevPdc?repsSuivantes(_perfReps(_prevPdc),_prevPdc.rir,_rirPrescrit(ex)):null;
  // isFemale ne garde plus l'ajustement ni le bandeau : currentCycle ne vaut
  // autre chose que 'ignore' QUE si l'athlète a répondu au modal de phase, et
  // ce modal ne s'ouvre QUE sur cycleSuivi === 'actif'. Le test de genre était
  // donc redondant — et nuisible dès que le réglage devient réversible depuis
  // le profil : il aurait annulé en silence ce qui vient d'être demandé.
  // getCycleFactor rend déjà 1 et getCycleLabel déjà null pour 'ignore' :
  // personne ne change de comportement aujourd'hui.
  // L'ajustement de cycle est intégré À LA CHARGE SUGGÉRÉE, il n'a plus de
  // colonne à lui. Une colonne « CYC » en plus faisait basculer tout le tableau
  // en mode carte : l'écran de séance ne ressemblait plus du tout à celui des
  // hommes, pour une information qui tient dans une phrase. Une seule charge
  // est affichée, celle à mettre sur la barre, et la raison de l'écart est
  // écrite dessous.
  const _facteurCycle=(cycle.factor!==1.0)?cycle.factor:1;
  // LE MATÉRIEL ET L'UNITÉ (arrondiCharge) : 63,75 kg d'haltères devient 64,
  // et en livres la suggestion tombe sur un multiple de 5 lb. Dans le sens du
  // changement depuis la dernière charge ; la charge du cycle, vers le bas.
  const _prevW=prev?parseFloat(prev.weight):NaN;
  const _sugArr=_sugBrut?arrondiSuggestion(_sugBrut,{ex,user:currentUser,depart:isFinite(_prevW)?_prevW:undefined}):null;
  // Le cycle : arrondiCharge vers le bas (comme roundWeight le faisait au pas de la barre).
  const sugAjustee=_facteurCycle!==1&&_sugArr?arrondiCharge(_sugArr*_facteurCycle,{ex,user:currentUser,sens:'bas'}):null;
  // EN DÉCHARGE, ELLE NE MONTE PAS : min(charge de référence, suggestion).
  const sug=plafondDecharge(sugAjustee||_sugArr,_prevW,isCW,!!woState.deload);
  // ⚠ LA PREMIÈRE SÉRIE REÇOIT LA CHARGE SUGGÉRÉE (30/09/2026), comme la
  //   consigne du coach pose sa charge : isAuto, bordure verte, « proposé ».
  //   Elle était affichée au-dessus du tableau et la case restait vide : il
  //   fallait la recopier à la main, à chaque exercice. Ni sur un exercice
  //   dont le coach fixe la charge (déjà posée plus haut), ni sur une
  //   dégressive (P1 / P2). sugPremiere : ce n'est pas une surcharge, l'encart
  //   « Ta charge monte toute seule » ne s'y pose pas.
  if(sug>0&&!isCardio(ex)&&pr.type!=='degressive'&&!(_cons&&_cons.kg!=null)){
    const s0=data.sets[0];
    if(s0&&!s0.done&&!s0.userEdited&&!s0.degressive&&!s0.rpeCible
      &&(s0.isAuto||!String(s0.weight==null?'':s0.weight).trim())){
      s0.weight=sug; s0.isAuto=true; s0.sugPremiere=true;
    }
  }
  const _aff=kg=>kgVersAffiche(kg,currentUser)+_unite();
  // QUAND LE TABLEAU PASSE EN CARTES : la regle est dans _seriesEnCartes, et
  // renderSets la lit aussi : l'en-tete et les lignes ne peuvent pas diverger.
  const isWide=pr.type==='degressive'||_seriesEnCartes(data);
  // Repère A1 / A2 sur un superset, numéro d'ordre sinon : c'est ainsi que
  // l'exercice est écrit sur la fiche papier.
  const rep=_repereEx(woState.exercises,idx);
  // ══ R23 — CE QUI EST LU UNE FOIS, ET CE QUI DECIDE DU REPLI ══════════
  const _contrainteHtml=_blocContrainteSeance(ex,idx);
  const _demandeVideo=!isCardio(ex)&&!!demandeVideoPour(ex.name,currentUser);
  const _consigneHtml=_htmlConsigneExo(ex);
  const _videoTech=_htmlVideoTechniqueExo(ex);
  const _consOuverte=_consigneOuverte(ex,data,prev,{contrainte:!!_contrainteHtml,demandeVideo:_demandeVideo});

  const html=`
      <div${estSS?' style="border-left:1px solid var(--border);padding-left:12px"':''}>
      <div class="wo-tete">
        <div class="wo-tete-txt">
          ${estSS?`<div class="wo-ss-rep">${rep}</div>`:''}
          <div class="ex-name wo-nom">${escapeHtml(ex.name)}</div>
          ${_htmlNoteExo(idx,ex)}
          <div class="wo-serie">${ex.series} séries × ${escapeHtml(ex.reps)} reps</div>
          <!-- La barre et ses deux compteurs. Un superset rend plusieurs cartes
               dans le même écran : c'est une CLASSE qui les marque, et
               woMajProgression ne garde que la première. -->
          <div class="wo-prog">
            <div class="wo-prog-h">
              <div class="progress-bar"><div class="progress-fill" id="wo-progress" style="--arc-pc:0"></div></div>
              <span id="wo-ex-count">0/0</span>
            </div>
            <span id="wo-set-count"></span>
          </div>
        </div>
        <div class="wo-cmd">
        ${_htmlBoutonRemplacer(idx,ex)}
        ${_htmlBoutonHistorique(idx,ex)}
        <button class="hit44" id="wo-calc-btn-${idx}" style="background:var(--surface-2);border:1px solid var(--border);border-radius:var(--r-2);color:var(--sub);font-size:var(--fs-xs);padding:6px 10px;cursor:pointer;font-family:Montserrat,sans-serif;white-space:nowrap;display:inline-flex;align-items:center;gap:6px;flex-shrink:0"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="square" stroke-linejoin="miter" width="13" height="13"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/></svg>Calculer ma charge</button>
        </div>
        <div class="wo-ava"></div>
      </div>

      ${cycleLabel&&!estSS?`<div style="background:var(--dark);border:1px solid var(--border);border-radius:var(--r-1);padding:10px 14px;margin-bottom:12px;font-size:var(--fs-xs);color:var(--sub);letter-spacing:.5px">${cycleLabel.text}</div>`:''}

      <!-- La consigne a ete recalculee sur ce qui a ete souleve. On le DIT :
           une charge qui change toute seule sans un mot se lit comme un bug,
           et c'est exactement ainsi que l'inverse avait ete rapporte. -->
      ${(_cons&&_cons.maxDepasse)?`<div style="background:var(--surface-2);border-left:1px solid var(--border);border-radius:var(--r-1);padding:10px 14px;margin-bottom:12px;font-size:var(--fs-xs);color:var(--text-dim);line-height:1.6">Tu as déjà fait mieux que le 1RM noté par ton coach sur cet exercice (${_cons.max} kg au dossier, ${_cons.maxObserve} kg estimés d’après tes séries). La charge du jour est calculée sur ce que tu soulèves vraiment.</div>`:''}

      ${isCardio(ex)?
        `<div style="background:#0a1a0a;border:1px solid #1a3a1a;border-radius:var(--r-3);padding:14px;margin-bottom:12px;text-align:center">
          <div style="font-size:var(--fs-2xl);margin-bottom:6px">${icon('activity',28)}</div>
          <div style="font-size:var(--fs-xl);font-weight:900;color:var(--green)">${escapeHtml(ex.reps)}</div>
          <div style="font-size:var(--fs-xs);color:var(--sub);margin-top:4px">Durée · Cardio</div>
        </div>`
      :_abandon?
      `<div class="wo-no-hist sub" style="font-size:var(--fs-xs);background:var(--surface-2);border-radius:var(--r-2);padding:10px 14px;margin-bottom:12px;line-height:1.6">
        Plus de quatre mois sans cette séance. Reprends à une charge que tu tiens facilement pour 10 répétitions, et laisse la progression repartir de là.
        <div style="color:var(--text-dim);margin-top:6px">${SUG_NOTE_REPERE}</div>
      </div>`
      :sug?`<div class="suggest-box">
        <div style="display:flex;gap:20px;align-items:flex-end;margin:2px 0 6px">
          <div><div style="font-size:var(--fs-2xl);font-weight:900;line-height:1">${_aff(sug)}${chargeParMain(ex)?'<span class="par-main">/main</span>':''}</div><div style="font-size:var(--fs-xs);color:#fca5a5;letter-spacing:.5px;margin-top:4px;font-weight:700">${isCW?'↓ Assistance : progresser = réduire':'Charge pour la première série'}</div></div>
        </div>
        <div class="s-note">${isCW?'Contrepoids : un RIR élevé fait diminuer la charge. ':''}${prev?'Basée sur '+escapeHtml(creneauRef)+' ('+_aff(prev.weight)+(prev.rir!==''&&prev.rir!=null?(String(prev.rir)==='echec'?' à l’échec':' à RIR '+prev.rir):', RIR non noté')+')':'Première séance'}</div>
        ${_decote<1?`<div class="s-note" style="margin-top:6px">Ta dernière séance de ${escapeHtml(ex.name)} date du ${_libDateRef(prev._refDate)}. On repart ${Math.round((1-_decote)*100)} % en dessous, le temps de te retrouver.<div style="color:var(--text-dim);margin-top:4px">${SUG_NOTE_REPERE}</div></div>`:''}
        ${sugAjustee?`<div class="s-note" style="color:var(--cycle-accent);margin-top:6px">Ajustée de ${Math.round((1-_facteurCycle)*100)} % pour ta phase de cycle : ${_aff(_sugArr)} d'habitude, ${_aff(sugAjustee)} aujourd'hui.</div>`:''}
      </div>`:
      _sugReps?`<div class="suggest-box sug-reps">
        <div style="display:flex;gap:20px;align-items:flex-end;margin:2px 0 6px">
          <div><div style="font-size:var(--fs-2xl);font-weight:900;line-height:1">${_sugReps.reps} reps</div><div style="font-size:var(--fs-xs);color:#fca5a5;letter-spacing:.5px;margin-top:4px;font-weight:700">Au poids du corps : progresser = une répétition de plus</div></div>
        </div>
        <div class="s-note">Basée sur ${escapeHtml(creneauRef)} (${_perfReps(_prevPdc)} reps${_sugReps.rir!=null?' à RIR '+_sugReps.rir:', RIR non noté'})${_sugReps.monte?' : il te restait de la réserve, vise une de plus.':' : garde le même nombre, et vise le RIR prévu.'}</div>
      </div>`:
      // Pas d'historique SUR CE CRÉNEAU. On le dit, au lieu de laisser un vide
      // inexpliqué — et surtout au lieu de proposer la charge d'un autre jour,
      // qui ne correspond ni aux mêmes répétitions ni au même effort.
      `<div id="wo-no-hist-${idx}" class="wo-no-hist sub" style="font-size:var(--fs-xs);background:var(--surface-2);border-radius:var(--r-2);padding:10px 14px;margin-bottom:12px;line-height:1.6">Pas encore d'historique pour cet exercice ${escapeHtml(creneauPhrase)} : note ta charge, elle servira de repère la prochaine fois.</div>`}

      ${_htmlMonteeCharge(sug,ex,idx)}
      ${_contrainteHtml}
      <!-- ══ R23, « COMMENT L'EXECUTER » ════════════════════════════════
           La CONSIGNE (tempo, materiel, vignette, description) et la VIDEO
           TECHNIQUE, dans un seul <details> : ils poussaient le tableau des
           series sous le pli sur un exercice que l'athlete connait deja.
           Rien n'est retire, tout est a un doigt. Voir _consigneOuverte pour
           la regle d'ouverture. hidden tant qu'il n'y a rien a montrer :
           renderWoEx le rend visible si l'index des illustrations apporte une
           image apres coup. -->
      <details id="wo-comment-${idx}" class="wo-comment"${_consOuverte?' open':''}${_videoTech?' data-video="1"':''}${(_consigneHtml||_videoTech)?'':' hidden'}>
        <summary class="wo-comment-s"><svg class="wo-comment-yt" viewBox="0 0 28 20" aria-hidden="true"><rect width="28" height="20" rx="5" fill="#FF0000"/><path d="M11.2 5.6v8.8L18.8 10z" fill="#fff"/></svg><span class="wo-comment-t"><span class="wo-comment-l">Comment l'exécuter</span>${ex.materiel?` <span class="wo-comment-m">· ${escapeHtml(ex.materiel)}</span>`:''}</span><span class="wo-comment-fl" aria-hidden="true">▾</span></summary>
        <!-- R15, LA CONSIGNE VIT DANS SA PROPRE ZONE : renderWoEx la repeint
             seule quand l'index des illustrations arrive apres le rendu. -->
        <div id="wo-consigne-${idx}">${_consigneHtml}</div>
        ${_videoTech}
      </details>

      ${!isCardio(ex)?banniereTechnique(ex,idx):''}
      ${!isCardio(ex)&&pr.type==='degressive'?`<div style="background:#7c2d1222;border:1px solid #9a3412;border-radius:var(--r-3);padding:10px 14px;margin-bottom:12px;font-size:var(--fs-sm);color:#fca5a5">
        <strong>Dégressive :</strong> Phase 1 → <strong>${pr.p1} reps</strong> lourd · Phase 2 → <strong>${pr.p2} reps</strong> léger (sans poser la charge)
      </div>`:''}

      ${_demandeVideo?`<div class="wo-demande-video" style="display:flex;align-items:center;gap:10px;background:var(--surface-2);border-radius:var(--r-2);padding:10px 14px;margin-bottom:12px;font-size:var(--fs-xs);color:var(--sub);line-height:1.6"><span style="flex-shrink:0">${icon('video',14)}</span><span>Ton coach t'a demandé une vidéo de cet exercice.</span></div>`:''}
      <!-- LA BANDE DE TEMPO. Peinte par renderSets, comme les actions de
           series : son libelle depend de la serie en cours et du chronometre,
           qui changent tous les deux sans repasser par _blocExo. Elle vit HORS
           du bloc CONSIGNE parce que la mesure existe MEME SANS TEMPO : un
           exercice sans consigne se chronometre comme les autres. -->
      ${!isCardio(ex)?`<div id="wo-tempo-${idx}"></div>`:''}
      ${isCardio(ex)?
        `<table class="series-table" style="width:100%"><thead><tr><th>#</th><th>Complété</th></tr></thead><tbody id="sets-body-${idx}"></tbody></table>`
      :`<div id="wo-sets-scroll-${idx}"${!isWide?' style="overflow-x:auto"':''}>
      <table class="series-table series-table-wo" style="width:100%${!isWide?';min-width:260px':''}">
        <thead><tr style="background:var(--red)">
          ${_enteteSeries(isWide,pr.type==='degressive',!_woTeteDeGroupe(idx),chargeParMain(ex))}
        </tr></thead>
        <tbody id="sets-body-${idx}"></tbody>
      </table>
      </div>`}
      <!-- AJOUTER / RETIRER UNE SERIE. Repeinte par renderSets et non posee
           ici une fois pour toutes : le « − » depend de l'etat de la derniere
           serie, qui change a chaque validation. -->
      <div id="wo-sets-actions-${idx}"></div>
      <div id="wo-douleur-${idx}"></div>
      <!-- R09 : L'ENCART DE LA PREMIERE CHARGE PROPOSEE. Sous la carte de
           douleur et non au-dessus : une question de securite passe avant
           une explication. Peint par renderSets, comme elle. -->
      <div id="wo-surcharge-${idx}"></div>
      ${ex.repos&&!isCardio(ex)&&!estSS?`<div style="margin-top:10px;display:flex;align-items:center;gap:8px;color:var(--sub);font-size:var(--fs-sm)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="square" stroke-linejoin="miter" width="15" height="15" style="flex-shrink:0"><circle cx="12" cy="14" r="8"/><line x1="12" y1="14" x2="12" y2="9.5"/><line x1="10" y1="2.5" x2="14" y2="2.5"/><line x1="12" y1="2.5" x2="12" y2="6"/></svg> <strong>Repos :</strong> ${escapeHtml(ex.repos)}</div>`:''}
      </div>`;

  return {idx,ex,data,sug,html};
}

// idx explicite : sur un superset, deux tableaux de séries coexistent à
// l'écran. Le laisser retomber sur woState.currentEx ferait écrire les deux
// dans le même exercice.
// Un plafond, pas une regle : vingt series sur un exercice, on est deja bien
// au-dela de ce qu'un programme prescrit. Il protege d'un doigt reste appuye.
const SERIES_MAX=20;
// LA SAISIE D'UN TEMPO, COTE COACH. C'est le SEUL endroit ou une
// normalisation a lieu : « 3110 » et « 3-1-1-0 » sont enregistres sous la
// meme forme, et le champ affiche ce qui a ete retenu — sans quoi l'ecran
// garderait « 3110 » pendant que le programme porte « 3-1-1-0 ».
//
// ⚠ CE QUI NE SE NORMALISE PAS EST CONSERVE TEL QUEL. Pas de refus, pas de
// correction, pas de champ vide : un coach qui ecrit « 2 s en bas, explosif »
// a ecrit une consigne, et elle vaut. Elle n'aura simplement pas de guide —
// il n'y a rien a battre dans une phrase.
// LE MATÉRIEL COMMENCE PAR UNE MAJUSCULE (Kevin, 01/10/2026) : la banque écrit
// « barre », la carte affiche « Barre ». Seule la première lettre change.
// L'IMAGE DE LA CARTE : la photo du coach, sinon l'illustration du guide.
function _imgCarte(ex){
  if(ex&&ex.image) return ex.image;
  try{ return illustrationExo(ex)||''; }catch(e){ return ''; }
}
// UN CHAMP DE LIEN VIDÉO : même normalisation et même avertissement pour les
// deux, deux champs qui se ressemblent doivent se comporter pareil.
function _champVideoCarte(ex,i,cle,libelle,aide){
  const brut=(ex&&ex[cle])||'';
  let u=''; try{ u=normaliserUrlVideo(brut); }catch(e){ u=''; }
  return `<div class="px-media-lien">
    <label style="margin-top:0">${libelle}</label>
    <div class="px-media-champ">
      <input value="${escapeHtml(brut)}" onchange="_progExDirty=true;progEx[${i}].${cle}=normaliserUrlVideo(this.value);this.value=progEx[${i}].${cle};renderProgEx()" placeholder="https://youtu.be/..." class="f-sm">
      ${u?`<a href="${safeUrl(u)}" target="_blank" rel="noopener" class="px-media-lire" aria-label="Ouvrir la vidéo">▶</a>`:''}
    </div>
    ${brut&&!u?`<div class="videoInutilisable" style="font-size:var(--fs-2xs);color:var(--orange);margin-top:4px;line-height:1.5">Ce texte n'est pas un lien : l'athlète ne verra aucune vidéo. Colle l'adresse YouTube, ou juste l'identifiant de la vidéo.</div>`:''}
    ${aide?`<div class="px-sous" style="white-space:normal">${escapeHtml(aide)}</div>`:''}
  </div>`;
}
// CE QUE L'ATHLÈTE VERRA SI LE SECOND CHAMP RESTE VIDE : la vidéo du guide pour
// la technique choisie, quand elle existe (videoMethodeExo fait ce repli).
function _aideVideoMethode(ex){
  if(ex&&ex.videoUrl2) return '';
  const m=(ex&&ex.methode&&TECHNIQUES[ex.methode])||null;
  if(!m) return 'À remplir seulement si une technique est posée sur l’exercice.';
  let v=''; try{ v=videoTechnique(m)||''; }catch(e){ v=''; }
  return v?('Vide : l’athlète verra la vidéo du guide pour « '+m.nom+' ».')
          :('Le guide n’a pas de vidéo pour « '+m.nom+' » : colle la tienne ici.');
}
function _materielMajuscule(v){
  const t=String(v==null?'':v).trim();
  return t?t.charAt(0).toLocaleUpperCase('fr')+t.slice(1):'';
}
function _progTempoSaisie(i,el){
  _progExDirty=true;
  const brut=String(el&&el.value!=null?el.value:'');
  const c=tempoNormalise(brut);
  const val=c||brut;
  progEx[i].tempo=val;
  if(el&&el.value!==val) el.value=val;
  return val;
}
// ══ LA CHARGE TAPEE, LUE UNE FOIS POUR TOUTES (30/09/2026) ═════════════
// En Chromium fr-FR, un <input type="number"> lit « 82,5 » comme 825 : la
// virgule y est un separateur de milliers. Les champs de charge sont donc des
// champs TEXTE (inputmode="decimal" garde le pave numerique), et c'est cette
// fonction qui dit ce qu'ils contiennent.
//
// PURE. « 82,5 », « 82.5 » et « 82 » sont acceptes ; tout le reste (lettres,
// signe, deux separateurs, vide) rend null. Arrondi au quart de kilo — le
// plus petit disque qui existe en salle —, borne a 0..max (500 par defaut).
const CHARGE_SAISIE_MAX=500;
function lireCharge(brut,max){
  const t=String(brut==null?'':brut).trim();
  if(!/^\d+(?:[.,]\d*)?$/.test(t)) return null;
  const x=parseFloat(t.replace(',','.'));
  if(!isFinite(x)) return null;
  const v=Math.round(x*4)/4;
  const m=(typeof max==='number'&&max>0)?max:CHARGE_SAISIE_MAX;
  return (v<0||v>m)?null:v;
}
// LA PRESSE, LE HACK, LA BARRE GUIDEE (06/10/2026) : 600 kg a la presse a
// cuisses existent, et le plafond de 500 les refusait. Ces exercices montent
// a CHARGE_SAISIE_MAX_MACHINE ; au-dela de 500, la saisie est CONFIRMEE
// (« 620 kg à la presse ? »), pas refusee. Tout le reste garde 500.
// PURE. `ex` : le nom de l'exercice, ou l'exercice ({name}). En kilos.
const CHARGE_SAISIE_MAX_MACHINE=1000;
const CHARGE_MATERIEL_LOURD=Object.freeze(['PRESSE','HACK','SMITH']);
function _chargeNomEx(ex){ return String(ex&&typeof ex==='object'?(ex.name||ex.nom||''):(ex||'')); }
function chargeLourde(ex){
  const nom=_chargeNomEx(ex);
  let m=[]; try{ m=materielExercice(nom)||[]; }catch(e){ m=[]; }
  if(m.some(k=>CHARGE_MATERIEL_LOURD.indexOf(k)>=0)) return m.find(k=>CHARGE_MATERIEL_LOURD.indexOf(k)>=0);
  const n=nom.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();
  return /PRESSE|LEG PRESS/.test(n)?'PRESSE':/HACK/.test(n)?'HACK':null;
}
function chargeMaxSaisie(ex){ return chargeLourde(ex)?CHARGE_SAISIE_MAX_MACHINE:CHARGE_SAISIE_MAX; }
const CHARGE_LIEU_LOURD=Object.freeze({PRESSE:'à la presse',HACK:'au hack squat',SMITH:'à la barre guidée'});
// La charge qui merite une question : plus de 1,5 fois la meilleure charge
// deja faite sur l'exercice, et plus de 20 kg. Sans historique, aucune
// question — il n'y a rien a comparer. En assistance, la « meilleure » charge
// est la plus FAIBLE : la regle ne s'y applique pas.
const CHARGE_SUSPECTE_FACTEUR=1.5, CHARGE_SUSPECTE_MIN_KG=20;
function chargeSuspecte(kg,user,nomEx){
  const v=Number(kg);
  if(!(v>CHARGE_SUSPECTE_MIN_KG)) return null;
  let r=null; try{ r=recordsExercice(user,nomEx); }catch(e){ r=null; }
  const mc=r&&r.meilleureCharge;
  if(!mc||mc.assiste||!(mc.kg>0)) return null;
  return v>CHARGE_SUSPECTE_FACTEUR*mc.kg?mc.kg:null;
}
// LA SAISIE D'UNE CHARGE, EN UN SEUL ENDROIT. Elle vivait dans un attribut
// onchange recopié à quatre exemplaires par le gabarit : un refus posé là ne
// serait vérifiable nulle part, et les copies finiraient par diverger.
//
// CE QUI NE SE LIT PAS EST REFUSE, PAS CORRIGE : on ne devine pas qu'un
// « -80 » voulait dire 80, ni qu'un « 8a » voulait dire 8. Le champ reprend
// la valeur d'avant et un toast le dit.
//
// Ce que le négatif coûtait : sur `weight`, tonnageSerie rend 0 et la série
// disparaît du tonnage sans un mot ; sur `weight2`, il n'y a AUCUN garde et
// la phase 2 RETRANCHE du tonnage de la séance. D'où le refus sur les deux.
//
// ET LE REFUS NE MARQUE PAS `userEdited` : ce drapeau coupe la charge
// proposée pour cette série jusqu'à la fin de la séance. Une faute de frappe
// ne doit pas priver quelqu'un de sa suggestion.
//
// UNE CHARGE AUX ANTIPODES DE L'HISTORIQUE EST CONFIRMEE avant d'etre ecrite
// (chargeSuspecte) : « 825 » pour « 82,5 » fausse d'un coup le record, le
// tonnage et la charge proposee de la seance suivante. La fonction rend alors
// la promesse de la question ; sinon, elle ecrit tout de suite.
function _woChargeSaisie(idx,i,champ,el){
  const d=woState&&woState.sessionData&&woState.sessionData[idx];
  const s=d&&d.sets&&d.sets[i];
  if(!s||!el) return;
  // Seule `weight` porte la charge proposée : `weight2` n'est jamais
  // auto-remplie, donc ni `userEdited` ni `isAuto` ne la concernent.
  const principal=champ!=='weight2';
  const lb=uniteCharge(currentUser)==='lb';
  const avant=String(_poidsSaisie(s[champ]));
  const tape=String(el.value).trim();
  const ecrire=(val)=>{
    s[champ]=val;
    if(principal){ s.userEdited=true; s.isAuto=false; }
    // R25 — PAS renderSets : il reconstruit tout le tbody, et le champ ou le
    // doigt vient d'arriver — la serie suivante — serait detruit avec son
    // clavier. On ne remplace que les lignes dont le rendu change, et celle
    // qui porte le focus est modifiee EN PLACE.
    _woMajLignes(woState.exercises[idx],d,idx);
  };
  // VIDER UN CHAMP reste une saisie volontaire, comme avant.
  if(tape===''){ el.value=''; ecrire(''); return; }
  const nomEx=woState.exercises[idx]&&woState.exercises[idx].name;
  const maxKg=chargeMaxSaisie(nomEx);
  const _max=lb?Math.round(maxKg/LB_KG):maxKg;
  const v=lireCharge(tape,_max);
  if(v==null){
    el.value=avant;
    toast(/^\s*-/.test(tape)?'Charge négative ignorée'
      :/^\d+(?:[.,]\d*)?$/.test(tape)?'Charge hors limites : '+_max+' '+(lb?'lb':'kg')+' au plus'
      :'Charge illisible : tape un nombre, par exemple 82,5','var(--orange)');
    _woMajLignes(woState.exercises[idx],d,idx);
    return;
  }
  // EN LIVRES, le dossier reçoit des kilos ; une saisie inchangée garde la
  // valeur stockée (pas de dérive d'arrondi).
  const inchangee=tape.replace(',','.')===avant;
  const kg=lb?(inchangee?Number(s[champ]):afficheVersKg(String(v),currentUser,s[champ])):v;
  const val=inchangee&&!lb?String(s[champ]):String(kg);
  // Le champ affiche ce qui a été retenu : deux vérités pour une saisie, jamais.
  el.value=lb?String(v):val;
  const record=inchangee?null:chargeSuspecte(kg,currentUser,nomEx);
  // Au-delà de 500 kg (presse, hack, barre guidée) : une question, même sans
  // historique. Une seule question si la charge est aussi suspecte.
  const lourde=!inchangee&&Number(kg)>CHARGE_SAISIE_MAX;
  if(record==null&&!lourde){ ecrire(val); return; }
  const u=lb?'lb':'kg', aff=x=>String(lb?kgVersAffiche(x,currentUser):x).replace('.',',');
  const lieu=lourde?CHARGE_LIEU_LOURD[chargeLourde(nomEx)]||'sur cette machine':'';
  return rcConfirm(aff(kg)+' '+u+(lieu?' '+lieu:'')+' ?',
    record!=null?'Ta meilleure charge sur cet exercice est '+aff(record)+' '+u+'. Confirme, ou corrige si une virgule a sauté.'
      :'C’est au-delà de 500 kg. Confirme, ou corrige si une virgule a sauté.',
    'Oui, c’est ça','Corriger').then(ok=>{
      if(ok){ ecrire(val); return true; }
      el.value=avant;
      _woMajLignes(woState.exercises[idx],d,idx);
      try{ el.focus(); el.select(); }catch(e){}
      return false;
    });
}
// ══ R29 — LES REPETITIONS FAITES, DANS UNE FOURCHETTE ═══════════════════
// Un entier de 1 a 999, ou rien : vide rend la prescription (repsDone retire),
// jamais 0 — une serie validee a zero repetition n'a pas eu lieu. Hors de la
// fourchette, on garde le chiffre : c'est ce qui a ete fait, et 13 sur un
// 10-12 dit justement qu'il est temps de charger.
function _woRepsSaisie(idx,i,el){
  const d=woState&&woState.sessionData&&woState.sessionData[idx];
  const s=d&&d.sets&&d.sets[i];
  if(!s||!el) return false;
  const brut=String(el.value).trim().replace(',','.');
  if(brut===''){
    delete s.repsDone;
  } else {
    const n=Number(brut);
    if(!Number.isInteger(n)||n<1||n>999){
      el.value=s.repsDone!=null?String(s.repsDone):'';
      toast('Répétitions : un nombre entier, 1 ou plus','var(--orange)');
      return false;
    }
    s.repsDone=n;
    if(el.value!==String(n)) el.value=String(n);
  }
  try{ woPersist(); }catch(e){}
  // Comme la charge (R25) : on ne repeint que ce qui change, le focus reste.
  _woMajLignes(woState.exercises[idx],d,idx);
  return true;
}
// ══ R25 — LA SAISIE ENCHAINEE DES CHARGES ═══════════════════════════════
//
// Ce que renderSets a rendu pour chaque tbody : _woMajLignes compare le rendu
// suivant a celui-ci, ligne par ligne.
const _woLignesRendues=new WeakMap();
// LE CHAMP SUIVANT, DANS CET EXERCICE SEULEMENT. L'ordre du document est celui
// qu'on veut : serie par serie, P1 puis P2 sur une degressive. Les champs d'une
// serie validee sont disabled, donc sautes. Un superset rend deux tbody : la
// recherche ne sort jamais de celui-ci.
function _woChampSuivant(tb,i,champ){
  const l=[...tb.querySelectorAll('input.set-input[data-serie]')].filter(x=>!x.disabled);
  const k=l.findIndex(x=>x.getAttribute('data-serie')===String(i)&&x.getAttribute('data-champ')===champ);
  return k>=0?(l[k+1]||null):null;
}
// UN ECOUTEUR PAR TBODY, DELEGUE, et aucun raccourci global : la cible est le
// clavier du telephone, dont la touche « Suivant » envoie Enter.
function _woBrancherEnchainement(tb,idx){
  if(!tb||tb._woEnchaine) return;
  tb._woEnchaine=true;
  tb.addEventListener('keydown',e=>{
    if(e.key!=='Enter') return;
    const el=e.target;
    if(!el||!el.matches||!el.matches('input.set-input[data-serie]')) return;
    e.preventDefault();
    const i=parseInt(el.getAttribute('data-serie'),10), champ=el.getAttribute('data-champ');
    // LA SAISIE EST VALIDEE ICI, AVANT DE PARTIR. Selon le navigateur, le
    // change du champ quitte part pendant ou apres le deplacement du focus ;
    // le faire d'abord rend l'ordre certain, et la serie suivante recoit sa
    // charge proposee avant d'etre atteinte. Le change qui suivra ne changera
    // plus rien. Rien n'est ecrit si la valeur n'a pas bouge : accepter la
    // charge proposee d'un « Suivant » ne la transforme pas en saisie.
    try{
      const d=woState&&woState.sessionData&&woState.sessionData[idx];
      const s=d&&d.sets&&d.sets[i];
      if(s){
        // Compare ce que le champ AFFICHE (en livres, la valeur convertie) :
        // « 82,5 » face a un dossier en « 82.5 » n'est pas une nouvelle saisie.
        const brut=String(el.value).trim().replace(',','.');
        const deja=champ==='repsDone'?String(s[champ]==null?'':s[champ]):String(_poidsSaisie(s[champ]));
        if(brut!==deja){
          // R29 — les repetitions d'une fourchette ont leur propre ecriture.
          if(champ==='repsDone') _woRepsSaisie(idx,i,el);
          else _woChargeSaisie(idx,i,champ,el);
        }
      }
    }catch(err){}
    const suivant=_woChampSuivant(tb,i,champ);
    if(suivant){
      try{ suivant.focus({preventScroll:false}); }catch(err){ try{ suivant.focus(); }catch(_){} }
      // La charge proposee est selectionnee : taper la remplace, « Suivant »
      // la garde.
      try{ suivant.select(); }catch(err){}
    } else {
      try{ el.blur(); }catch(err){}
    }
  });
}
// ── NE REMPLACER QUE CE QUI CHANGE ──────────────────────────────────────
// Le remplissage automatique tourne dans renderSets, a l'identique (mode
// lignesSeules) : chargeSuivante, isAuto et userEdited ne sont lus et ecrits
// qu'a un seul endroit. On compare ensuite chaque ligne a son rendu precedent.
// Une ligne inchangee n'est pas touchee ; une ligne changee est remplacee —
// modifiee EN PLACE : ses champs restent les memes elements.
//
// ⚠ POURQUOI EN PLACE, ET PAS SEULEMENT LA LIGNE FOCALISEE. Toucher la case de
// la serie suivante du doigt deplace le focus, et le change du champ quitte
// part AVANT que la case touchee ne le recoive. Remplacer sa ligne a ce
// moment-la detruisait la case sous le doigt : le focus tombait dans le vide
// et le clavier se fermait. Garder les elements rend l'ordre des evenements
// indifferent.
// REPLI : si le nombre de lignes a change, ou si la ligne focalisee n'a plus la
// meme structure, renderSets complet, puis le focus est rendu au meme champ,
// curseur compris.
function _woMajLignes(ex,data,idx){
  const tb=document.getElementById('sets-body-'+idx);
  const avant=tb&&_woLignesRendues.get(tb);
  if(!tb||!avant||isCardio(ex)||tb.rows.length!==avant.length) return _woRenduCompletFocus(ex,data,idx);
  const apres=renderSets(ex,data,idx,{lignesSeules:true});
  if(!Array.isArray(apres)||apres.length!==avant.length) return _woRenduCompletFocus(ex,data,idx);
  const lignes=[...tb.rows];
  for(let i=0;i<apres.length;i++){
    if(apres[i]===avant[i]) continue;
    const z=document.createElement('tbody');
    z.innerHTML=apres[i];
    const neuf=z.firstElementChild, vieux=lignes[i];
    if(!neuf||!vieux) return _woRenduCompletFocus(ex,data,idx);
    if(!_woPatcherNoeud(vieux,neuf)){
      if(vieux.contains(document.activeElement)) return _woRenduCompletFocus(ex,data,idx);
      vieux.replaceWith(neuf);
    }
  }
  _woLignesRendues.set(tb,apres);
  _majActionsSeries(ex,data,idx);
  try{ _majBandeTempo(ex,data,idx); }catch(e){}
  _majCarteDouleur(idx);
  _majEncartSurcharge(idx);
}
// Met `vieux` a l'image de `neuf` en gardant ses elements : un champ reste le
// meme champ, donc garde son focus et son clavier. Rend false si les deux
// arbres n'ont pas la meme forme — l'appelant remplace alors la ligne, ou
// repasse par le rendu complet si le focus est dedans.
function _woPatcherNoeud(vieux,neuf){
  if(!vieux||!neuf||vieux.nodeType!==neuf.nodeType) return false;
  if(vieux.nodeType===3){ if(vieux.nodeValue!==neuf.nodeValue) vieux.nodeValue=neuf.nodeValue; return true; }
  if(vieux.nodeType!==1) return true;
  if(vieux.tagName!==neuf.tagName) return false;
  // Les attributs : ceux du nouveau rendu, et seulement eux.
  for(const a of [...vieux.attributes]) if(!neuf.hasAttribute(a.name)) vieux.removeAttribute(a.name);
  for(const a of [...neuf.attributes]) if(vieux.getAttribute(a.name)!==a.value) vieux.setAttribute(a.name,a.value);
  if(vieux.tagName==='INPUT'){
    // La valeur AFFICHEE suit le dossier : la charge proposee de la serie
    // suivante arrive dans la case, meme si le doigt y est deja.
    const v=neuf.getAttribute('value')||'';
    if(vieux.value!==v) vieux.value=v;
    vieux.disabled=neuf.hasAttribute('disabled');
    return true;
  }
  // LES ENFANTS, DANS L'ORDRE. Le cas courant est une mention qui apparait ou
  // disparait APRES le champ — « proposé » sous la charge : le champ, en tete,
  // est garde, la mention ajoutee ou retiree derriere lui.
  const vk=[...vieux.childNodes], nk=[...neuf.childNodes];
  const n=Math.min(vk.length,nk.length);
  for(let k=0;k<n;k++){
    if(!_woPatcherNoeud(vk[k],nk[k])){
      if(vk[k].nodeType===1&&vk[k].contains(document.activeElement)) return false;
      vk[k].replaceWith(nk[k]);
    }
  }
  for(let k=n;k<vk.length;k++){
    if(vk[k].nodeType===1&&vk[k].contains(document.activeElement)) return false;
    vk[k].remove();
  }
  for(let k=n;k<nk.length;k++) vieux.appendChild(nk[k]);
  return true;
}
// LE REPLI (b) : rendu complet, puis le focus rendu au meme champ de la meme
// serie, position du curseur comprise quand le type de champ la donne.
function _woRenduCompletFocus(ex,data,idx){
  const a=document.activeElement;
  const tb=document.getElementById('sets-body-'+idx);
  const garde=(a&&tb&&tb.contains(a)&&a.matches&&a.matches('input.set-input[data-serie]'))
    ?{serie:a.getAttribute('data-serie'),champ:a.getAttribute('data-champ'),
      debut:(()=>{ try{ return a.selectionStart; }catch(e){ return null; } })(),
      fin:(()=>{ try{ return a.selectionEnd; }catch(e){ return null; } })()}:null;
  renderSets(ex,data,idx);
  if(!garde) return;
  const t=document.getElementById('sets-body-'+idx);
  const el=t&&t.querySelector('input.set-input[data-serie="'+garde.serie+'"][data-champ="'+garde.champ+'"]');
  if(!el||el.disabled) return;
  try{ el.focus({preventScroll:true}); }catch(e){}
  if(garde.debut!=null) try{ el.setSelectionRange(garde.debut,garde.fin); }catch(e){}
}
// LA FORME EST COPIEE, PAS REECRITE. La derniere serie porte, par
// construction, la forme de _blocExo — y compris `degressive` et `p2reps`,
// dont depend la mise en page du tableau. La recopier puis remettre a zero ce
// qui appartient a la serie precedente rend la divergence impossible.
function _nouvelleSerie(idx){
  const ex=woState.exercises[idx];
  const d=woState.sessionData[idx];
  const pr=parseReps(ex.reps);
  const der=(d.sets||[])[d.sets.length-1]||null;
  const s=der?Object.assign({},der):{weight:'',weight2:'',
    reps:pr.type==='degressive'?pr.p1:ex.reps,rir:'',pain:'',done:false,
    degressive:pr.type==='degressive',p2reps:pr.p2};
  // Tout ce qui decrit la serie PRECEDENTE repart a zero. `reps` reste :
  // c'est la prescription en cours, et c'est ce qu'on veut refaire.
  s.weight=''; s.weight2=''; s.rir=''; s.pain=''; s.done=false;
  delete s.userEdited; delete s.isAuto; delete s.reposReel; delete s.tValid;
  // Le TUT decrit la serie PRECEDENTE : le recopier ferait entrer une mesure
  // qui n'a jamais eu lieu dans la moyenne qui juge un plateau.
  delete s.tut;
  return s;
}
// La charge n'est pas posee ici : renderSets la deduira du RIR de la serie
// precedente, exactement comme pour une serie prevue au programme.
function ajouterSerie(idx){
  const ex=woState&&woState.exercises&&woState.exercises[idx];
  const d=woState&&woState.sessionData&&woState.sessionData[idx];
  if(!ex||!d||!Array.isArray(d.sets)) return;
  // Cardio : une duree, pas un nombre de series.
  if(isCardio(ex)) return;
  if(d.sets.length>=SERIES_MAX)
    return toast('Vingt séries sur un exercice, c\'est déjà le maximum.','var(--orange)');
  d.sets.push(_nouvelleSerie(idx));
  renderSets(ex,d,idx);
  try{ woMajCompteurSeries(); }catch(e){}
  woPersist();
}
// Ne retire QUE la derniere, et seulement si elle n'est pas validee : une
// serie validee compte deja dans le tonnage, et retirer au milieu decalerait
// les index que _recordsVus et les gestionnaires du tableau portent en dur.
function retirerSerie(idx){
  const d=woState&&woState.sessionData&&woState.sessionData[idx];
  if(!d||!Array.isArray(d.sets)) return;
  const n=d.sets.length;
  // Une seule serie restante : la retirer reviendrait a supprimer
  // l'exercice, ce que ce bouton ne dit pas faire.
  if(n<=1) return;
  const der=d.sets[n-1];
  if(!der||der.done===true) return;
  const _oter=()=>{ d.sets.pop(); renderSets(woState.exercises[idx],d,idx); try{ woMajCompteurSeries(); }catch(e){} woPersist(); };
  // Une charge TAPEE A LA MAIN, un RIR ou une douleur : c'est de la saisie, et
  // elle disparaitrait sans un mot. La charge AUTO ne compte pas — elle est
  // proposee et non saisie, et poserait la question a chaque fois.
  const _saisie=!!(der.userEdited||(der.rir!==''&&der.rir!=null)
    ||(der.pain!==''&&der.pain!=null));
  if(!_saisie) return _oter();
  // Le refus — bouton « Garder » ou toucher du voile — conserve la serie.
  rcConfirm('Retirer cette série ?','Ce que tu as noté dessus sera perdu.',
    'Retirer','Garder').then(ok=>{ if(ok) _oter(); });
}
// Les deux boutons, sous le tableau. Repeints a chaque renderSets : le « − »
// n'existe que tant que la derniere serie n'est pas validee.
function _majActionsSeries(ex,data,idx){
  const z=document.getElementById('wo-sets-actions-'+idx);
  if(!z) return;
  // VIDE EXPLICITEMENT pour un cardio : un remplacement en cours de seance
  // peut changer le type de l'exercice, et les boutons resteraient sinon.
  if(isCardio(ex)){ z.innerHTML=''; return; }
  const n=((data&&data.sets)||[]).length;
  const der=n?data.sets[n-1]:null;
  const peutRetirer=n>1&&der&&der.done!==true;
  const base='min-height:44px;border-radius:var(--r-2);cursor:pointer;font-family:Montserrat,sans-serif;font-weight:800;letter-spacing:.5px;display:inline-flex;align-items:center;justify-content:center;gap:8px';
  z.innerHTML='<div style="display:flex;gap:8px;margin-top:10px">'
    +'<button type="button" class="hit44" onclick="ajouterSerie('+idx+')" '
    +'aria-label="Ajouter une série à cet exercice" '
    +'style="flex:1;'+base+';background:var(--surface-2);border:1px dashed var(--border);'
    +'color:var(--sub);font-size:var(--fs-xs)">'
    +'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" '
    +'stroke-linecap="square" width="13" height="13" aria-hidden="true">'
    +'<path d="M12 5v14"/><path d="M5 12h14"/></svg>une série</button>'
    // « FILMER » — LE PREMIER DES DEUX GESTES. Il vise la serie EN COURS et
    // ouvre directement la camera : aucun ecran intermediaire, aucune
    // question. Absent quand aucune serie n'est visee.
    +(_videoSerieVisee(data)>=0
      ?'<button type="button" class="hit44" onclick="filmerSerie('+idx+')" '
        +'aria-label="Filmer cette série" title="Filmer cette série" '
        +'style="width:52px;'+base+';background:none;border:1px solid var(--border);'
        +'color:var(--text-faint)">'
        +'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" '
        +'stroke-linecap="square" stroke-linejoin="miter" width="14" height="14" aria-hidden="true">'
        +'<path d="M23 7l-7 5 7 5V7z"/><rect x="1" y="5" width="15" height="14" rx="2"/>'
        +'</svg></button>'
      :'')
    +(peutRetirer
      ?'<button type="button" class="hit44" onclick="retirerSerie('+idx+')" '
        +'aria-label="Retirer la dernière série" title="Retirer la dernière série" '
        +'style="width:52px;'+base+';background:none;border:1px solid var(--border);'
        +'color:var(--text-faint)">'
        +'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" '
        +'stroke-linecap="square" width="13" height="13" aria-hidden="true">'
        +'<path d="M5 12h14"/></svg></button>'
      :'')
    +'</div>';
}
// ══════════════ LE GUIDE DE TEMPO ET LE CHRONOMETRE ════════════════════
//
// ⚠ COUPE PAR DEFAUT, ET IL N'Y A AUCUN MOYEN DE LE RENDRE AUTOMATIQUE. Un
// metronome impose sur chaque serie est insupportable en trois seances : on
// l'aurait desactive une fois pour toutes, et la mesure serait partie avec.
// D'ou la separation qui commande tout ce bloc — LE CHRONOMETRE ET LE GUIDE
// SONT DEUX GESTES DIFFERENTS. Le chronometre marche seul, sans tempo, sans
// vibration et sans point qui tourne ; le guide, lui, demarre le chronometre
// en plus du metronome. On peut mesurer sans etre guide, jamais l'inverse.
//
// L'ETAT EST UNIQUE POUR TOUTE LA PAGE : une seule serie se fait a la fois.
let _tempoEtat={actif:false,guide:false,idx:null,set:null,
                debut:0,rep:0,repsCible:0,phase:0,minuteur:null,peintre:null};

// PURE. La serie en cours d'un exercice : la premiere non validee. C'est
// celle que l'athlete est en train de faire, et donc celle que la mesure doit
// porter. Rend -1 quand tout est valide.
function _tempoSetCourant(data){
  const sets=(data&&data.sets)||[];
  for(let i=0;i<sets.length;i++) if(sets[i]&&!sets[i].done) return i;
  return -1;
}
// LA VIBRATION, AVEC REPLI SILENCIEUX. navigator.vibrate n'existe pas sur
// iOS : le guide visuel doit continuer sans erreur et sans le dire — annoncer
// « votre appareil ne vibre pas » a chaque serie serait un reproche fait au
// telephone.
function _tempoVibrer(ms){
  try{
    if(!navigator||typeof navigator.vibrate!=='function') return false;
    return !!navigator.vibrate(ms);
  }catch(e){ return false; }
}
function tempoVibrationDisponible(){
  try{ return !!(navigator&&typeof navigator.vibrate==='function'); }catch(e){ return false; }
}
// LE DEMARRAGE. `guide` distingue les deux gestes ; le reste est commun,
// parce que le chronometre est le meme dans les deux cas.
function tempoDemarrer(idx,guide){
  const ex=woState&&woState.exercises&&woState.exercises[idx];
  const data=woState&&woState.sessionData&&woState.sessionData[idx];
  if(!ex||!data) return false;
  const i=_tempoSetCourant(data);
  if(i<0) return false;
  // Le guide ne part QUE sur un tempo normalise : sans quatre durees, il n'y
  // a rien a battre. Le chronometre, lui, part toujours.
  const sec=tempoSecondes(tempoAffiche(ex));
  if(guide&&!sec) return false;
  tempoArreter(false);
  const reps=Number(_perfReps(data.sets[i]));
  _tempoEtat={actif:true,guide:!!(guide&&sec),idx:idx,set:i,
    debut:Date.now(),rep:0,repsCible:(isFinite(reps)&&reps>0)?reps:0,
    phase:0,minuteur:null,peintre:null};
  if(_tempoEtat.guide) _tempoPhase(sec,0);
  // Le compteur de secondes se repeint sans toucher au tableau : redessiner
  // les series une fois par seconde ferait perdre le focus d'un champ ouvert.
  _tempoEtat.peintre=setInterval(()=>{ try{ _majBandeTempo(ex,data,idx); }catch(e){} },1000);
  try{ _majBandeTempo(ex,data,idx); }catch(e){}
  return true;
}
// LE METRONOME. Une phase, sa vibration, puis la suivante. Les pauses a zero
// seconde sont traversees sans etre annoncees.
function _tempoPhase(sec,p){
  if(!_tempoEtat.actif||!_tempoEtat.guide) return;
  // Fin de la repetition : on compte, et on s'arrete au nombre prescrit.
  if(p>=4){
    _tempoEtat.rep++;
    if(_tempoEtat.repsCible>0&&_tempoEtat.rep>=_tempoEtat.repsCible){
      // TROIS VIBRATIONS POUR LA FIN : distinctes du battement de phase.
      _tempoVibrer([90,70,90,70,90]);
      tempoArreter(true);
      return;
    }
    p=0;
  }
  _tempoEtat.phase=p;
  const d=Number(sec[p])||0;
  // UNE PAUSE A ZERO N'EXISTE PAS : on enchaine sans battement ni attente.
  if(d<=0){ _tempoPhase(sec,p+1); return; }
  // Le battement marque le DEBUT de la phase : c'est le moment ou le geste
  // change de sens, et c'est ce que l'athlete doit sentir.
  _tempoVibrer(p===0||p===2?60:35);
  try{ _tempoPeindrePoint(); }catch(e){}
  _tempoEtat.minuteur=setTimeout(()=>_tempoPhase(sec,p+1),d*1000);
}
// L'ARRET. `mesurer` distingue la fin normale d'une annulation : un guide
// interrompu au milieu de la troisieme repetition n'a pas mesure la serie.
//
// LA MESURE EST ECRITE ICI ET NULLE PART AILLEURS, et elle passe par tutBorne :
// un chronometre oublie rend null, pas vingt minutes.
function tempoArreter(mesurer){
  const e=_tempoEtat;
  if(e.minuteur) clearTimeout(e.minuteur);
  if(e.peintre) clearInterval(e.peintre);
  const idx=e.idx, i=e.set;
  let ecrit=null;
  if(e.actif&&mesurer&&idx!=null&&i!=null){
    const data=woState&&woState.sessionData&&woState.sessionData[idx];
    const s=data&&data.sets&&data.sets[i];
    if(s){
      s.tut=tutBorne((Date.now()-e.debut)/1000);
      ecrit=s.tut;
      try{ woPersist(); }catch(err){}
    }
  }
  _tempoEtat={actif:false,guide:false,idx:null,set:null,
              debut:0,rep:0,repsCible:0,phase:0,minuteur:null,peintre:null};
  if(idx!=null){
    const ex=woState&&woState.exercises&&woState.exercises[idx];
    const data=woState&&woState.sessionData&&woState.sessionData[idx];
    if(ex&&data) try{ _majBandeTempo(ex,data,idx); }catch(err){}
  }
  return ecrit;
}
// Le point qui parcourt les quatre phases. Repeint seul, sans passer par le
// tableau : c'est quatre fois par repetition.
function _tempoPeindrePoint(){
  const z=document.getElementById('wo-tempo-point');
  if(!z) return false;
  z.textContent=TEMPO_PHASES[_tempoEtat.phase].lib;
  const pts=z.parentNode?z.parentNode.querySelectorAll('.tempo-pt'):[];
  for(let k=0;k<pts.length;k++)
    pts[k].style.background=(k===_tempoEtat.phase)?'var(--red)':'var(--border)';
  return true;
}
// LA BANDE. Deux boutons au plus, et rien quand il n'y a plus de serie a
// faire — une bande de mesure sur un exercice termine n'est qu'un bouton de
// plus a ne pas toucher.
function _majBandeTempo(ex,data,idx){
  const z=document.getElementById('wo-tempo-'+idx);
  if(!z) return false;
  const i=_tempoSetCourant(data);
  const enCours=_tempoEtat.actif&&_tempoEtat.idx===idx;
  if(i<0&&!enCours){ z.innerHTML=''; return true; }
  const guidable=!!tempoSecondes(tempoAffiche(ex));
  const B='style="flex:1;min-width:0"';
  let h='<div style="display:flex;gap:8px;align-items:center;margin-bottom:10px">';
  if(enCours){
    const s=Math.max(0,Math.round((Date.now()-_tempoEtat.debut)/1000));
    h+='<button class="btn btn-red btn-sm" '+B+' onclick="tempoArreter(true)">'
      +'Terminer · '+Math.floor(s/60)+':'+String(s%60).padStart(2,'0')+'</button>';
    if(_tempoEtat.guide){
      h+='<div style="flex:1;min-width:0;display:flex;align-items:center;gap:6px">'
        +TEMPO_PHASES.map(()=>'<span class="tempo-pt" style="width:7px;height:7px;'
          +'border-radius:var(--r-full);background:var(--border);flex:none"></span>').join('')
        +'<span id="wo-tempo-point" style="font-size:var(--fs-2xs);color:var(--sub);'
        +'white-space:nowrap;overflow:hidden;text-overflow:ellipsis"></span></div>';
    }
  } else {
    h+='<button class="btn btn-outline btn-sm" '+B+' onclick="tempoDemarrer('+idx+',false)">'
      +'Démarrer la série</button>';
    // « Guider » n'apparait QUE sur un tempo normalise, et il ne part jamais
    // seul : c'est un appui, a chaque serie, et c'est ce qui le rend
    // supportable.
    if(guidable)
      h+='<button class="btn btn-outline btn-sm" '+B+' onclick="tempoDemarrer('+idx+',true)">'
        +'Guider</button>';
  }
  h+='</div>';
  z.innerHTML=h;
  if(enCours&&_tempoEtat.guide) try{ _tempoPeindrePoint(); }catch(e){}
  return true;
}
// ══ QUAND LE TABLEAU PASSE EN CARTES ═══════════════════════════════════
//
// R14 — SEULEMENT SUR UNE SERIE DEGRESSIVE, comme avant R08. Les segments RIR
// qui forcaient les cartes sont retires (Kevin, 17/09/2026 : la mise en page
// etait illisible) : le RIR et la gene sont deux menus deroulants, et le
// tableau garde ses cinq colonnes. Une degressive a deux charges par ligne :
// elle seule ne tient pas en colonnes.
function _seriesEnCartes(data){
  const sets=(data&&Array.isArray(data.sets))?data.sets:[];
  return !!(sets[0]&&sets[0].degressive);
}
// ══ R15 / R16 — LES LISTES DU RIR ET DE LA GENE ═════════════════════════
//
// LES VALEURS ENREGISTREES NE CHANGENT PAS. RIR : 'echec', '0' a '5', celles
// d'avant R08 : chargeSuivante, l'e1RM et rirMoyenSeance les lisent telles
// quelles. Gene : '1' a '6' : DLR_SEANCE_SEUIL lit toujours 4.
// [valeur, ce que la case affiche, la definition]. La definition n'est que
// dans la liste, en petit : la case du tableau n'affiche que la valeur.
// R16 — une majuscule en tete de chaque definition (Kevin, 17/09/2026).
const RIR_CHOIX=Object.freeze([
  ['echec','Échec','Tu n\'as pas réussi à finaliser ton nombre de reps'],
  ['0','0','Aucune rep de plus possible'],
  ['1','1','Encore 1 rep en réserve'],
  ['2','2','Encore 2 reps en réserve'],
  ['3','3','Encore 3 reps en réserve'],
  ['4','4','Encore 4 reps en réserve'],
  ['5','5','5 reps ou plus en réserve']
]);
// R16 — LA GENE PREND LE DESSIN DU RIR, et 2 et 5 recoivent leur explication.
// Les mots sont ceux de l'entree « douleur » du lexique : 1 a 2 « À peine
// perceptible », 3 « Gênant mais supportable », 4 a 5 « Ça fait mal, ta
// technique se dégrade », 6 « Je dois arrêter ». Pour 2 et 5, qui partagent
// une ligne du lexique avec leur voisin, la definition dit ce qui les en
// distingue, sans rien ajouter que le lexique ne dise deja.
const GENE_CHOIX=Object.freeze([
  ['1','1','À peine perceptible'],
  ['2','2','Perceptible, sans gêner le mouvement'],
  ['3','3','Gênant mais supportable'],
  ['4','4','Ça fait mal'],
  ['5','5','Ça fait mal, ta technique se dégrade'],
  ['6','6','Je dois arrêter']
]);
// CE QUI DISTINGUE LES DEUX LISTES, et rien d'autre.
// ⚠ LA GENE S'OUVRE SUR UNE SERIE VALIDEE, LE RIR NON : une douleur se declare
// souvent une fois la barre reposee, le RIR decrit un effort accompli.
// ⚠ LA GENE PERSISTE AVANT DE REPEINDRE, LE RIR NON : ce sont les deux
// onchange d'origine, repris tels quels. La douleur doit etre dans
// l'instantane meme si le rendu echoue.
const WO_CHOIX=Object.freeze({
  rir:Object.freeze({champ:'rir',choix:RIR_CHOIX,id:'rir-menu',caseCls:'rir-choix',
    titre:'RIR de la série ',effacer:'Effacer le RIR noté',siValidee:false,persister:false}),
  gene:Object.freeze({champ:'pain',choix:GENE_CHOIX,id:'gene-menu',caseCls:'gene-choix',
    titre:'Gêne ressentie sur la série ',effacer:'Effacer la gêne notée',siValidee:true,persister:true})
});
// La liste ouverte, une seule a la fois : {genre, idx, i, btn, voile, menu}.
let _woChoix=null;
function woChoixFermer(rendreFocus){
  const m=_woChoix;
  if(!m) return false;
  _woChoix=null;
  try{ m.voile.remove(); m.menu.remove(); }catch(e){}
  window.removeEventListener('scroll',_woChoixSurDefilement,true);
  window.removeEventListener('resize',_woChoixSurDefilement);
  if(m.btn){
    m.btn.setAttribute('aria-expanded','false');
    if(rendreFocus&&m.btn.isConnected) try{ m.btn.focus({preventScroll:true}); }catch(e){}
  }
  return true;
}
// Le nom de R15, garde : il est appele par la suite de tests.
function rirMenuFermer(rendreFocus){ return woChoixFermer(rendreFocus); }
// SOUS LA CASE, ou AU-DESSUS quand la place manque en bas ; toujours dans
// l'ecran, a 8 px du bord.
function _woChoixPlacer(){
  const m=_woChoix;
  if(!m) return false;
  const r=m.btn.getBoundingClientRect();
  const vh=window.innerHeight, vw=window.innerWidth;
  // La case est sortie de l'ecran : la liste n'a plus rien a designer.
  if(!m.btn.isConnected||r.bottom<0||r.top>vh){ woChoixFermer(false); return false; }
  const mh=m.menu.offsetHeight, mw=m.menu.offsetWidth;
  let top=r.bottom+4;
  if(top+mh>vh-8) top=r.top-4-mh;
  top=Math.max(8,Math.min(top,vh-8-mh));
  m.menu.style.top=top+'px';
  m.menu.style.left=Math.max(8,Math.min(r.left,vw-8-mw))+'px';
  return true;
}
// LA PAGE DEFILE : la liste SUIT sa case, elle ne se ferme pas. La fermer au
// premier evenement de defilement la faisait disparaitre sous le doigt des
// qu'un defilement doux ou une inertie finissait sa course : constate.
// Le defilement DANS la liste ne la deplace pas.
function _woChoixSurDefilement(e){
  if(_woChoix&&e&&e.target&&e.target.nodeType===1&&_woChoix.menu.contains(e.target)) return;
  _woChoixPlacer();
}
function _woChoixSerie(idx,i){
  const d=woState&&woState.sessionData&&woState.sessionData[idx];
  return d&&Array.isArray(d.sets)?(d.sets[i]||null):null;
}
function _woChoixOuvrir(genre,idx,i,btn){
  woChoixFermer(false);
  const c=WO_CHOIX[genre];
  const s=_woChoixSerie(idx,i);
  // UNE SERIE VALIDEE N'OUVRE PAS SON RIR : le bouton est disabled, et on le
  // redit ici pour un appel direct.
  if(!c||!s||!btn||(s.done&&!c.siValidee)) return false;
  const cur=s[c.champ]==null?'':String(s[c.champ]);
  // « — » n'apparait que s'il y a quelque chose a effacer.
  const opts=c.choix.concat(cur!==''?[['','-',c.effacer]]:[]);
  const voile=document.createElement('div');
  voile.className='rir-menu-voile';
  // AU CLIC ET NON AU pointerdown : fermee des l'appui, la liste laisserait le
  // relachement tomber sur ce qu'il y a dessous, la case d'une autre serie.
  voile.addEventListener('click',e=>{ e.preventDefault(); woChoixFermer(true); });
  // `liste` et non `menu` : la suite de tests releve les affectations sur tout
  // nom finissant par « u » pour verifier la classification des champs du
  // dossier, et la classe de la liste s'y lisait comme un champ inconnu.
  const liste=document.createElement('div');
  liste.className='rir-menu';
  liste.id=c.id;
  liste.setAttribute('role','listbox');
  liste.setAttribute('aria-label',c.titre+(i+1));
  liste.innerHTML=opts.map(([v,l,def])=>`<button type="button" role="option" class="rir-opt" data-v="${v}" aria-selected="${cur===v}">`
    +`<span class="rir-opt-v">${l}</span><span class="rir-opt-d">(${escapeHtml(def)})</span></button>`).join('');
  liste.addEventListener('click',e=>{
    const o=e.target.closest('.rir-opt');
    if(o) _woChoixEcrire(genre,idx,i,o.getAttribute('data-v'));
  });
  liste.addEventListener('keydown',e=>{
    const l=[...liste.querySelectorAll('.rir-opt')];
    const k=l.indexOf(document.activeElement);
    let n=null;
    if(e.key==='ArrowDown') n=l[Math.min(l.length-1,k+1)];
    else if(e.key==='ArrowUp') n=l[Math.max(0,k-1)];
    else if(e.key==='Home') n=l[0];
    else if(e.key==='End') n=l[l.length-1];
    else if(e.key==='Escape'){ e.preventDefault(); woChoixFermer(true); return; }
    else if(e.key==='Tab'){ woChoixFermer(true); return; }
    if(n){ e.preventDefault(); n.focus(); }
  });
  document.body.appendChild(voile);
  document.body.appendChild(liste);
  btn.setAttribute('aria-expanded','true');
  _woChoix={genre,idx,i,btn,voile,menu:liste};
  if(!_woChoixPlacer()) return false;
  window.addEventListener('scroll',_woChoixSurDefilement,true);
  window.addEventListener('resize',_woChoixSurDefilement);
  const f=liste.querySelector('[aria-selected="true"]')||liste.querySelector('.rir-opt');
  if(f) try{ f.focus({preventScroll:true}); }catch(e){}
  return true;
}
function rirMenuOuvrir(idx,i,btn){ return _woChoixOuvrir('rir',idx,i,btn); }
function geneMenuOuvrir(idx,i,btn){ return _woChoixOuvrir('gene',idx,i,btn); }
// LE CHOIX. Ecrit ce qu'ecrivait le menu natif, au meme endroit, puis
// repeint : la charge de la serie suivante se recalcule sur le RIR, la carte
// de douleur se leve sur la gene.
function _woChoixEcrire(genre,idx,i,v){
  woChoixFermer(false);
  const c=WO_CHOIX[genre];
  const s=_woChoixSerie(idx,i);
  if(!c||!s||(s.done&&!c.siValidee)) return false;
  v=String(v==null?'':v);
  if(v!==''&&!c.choix.some(x=>x[0]===v)) return false;
  s[c.champ]=v;
  if(c.persister) woPersist();
  renderSets(woState.exercises[idx],woState.sessionData[idx],idx);
  // Le focus revient sur la case repeinte, pas en haut de la page.
  const tr=document.querySelectorAll('#sets-body-'+idx+' tr')[i];
  const b=tr&&tr.querySelector('.'+c.caseCls);
  if(b) try{ b.focus({preventScroll:true}); }catch(e){}
  return true;
}
function _woRirChoisir(idx,i,v){ return _woChoixEcrire('rir',idx,i,v); }
function _woGeneChoisir(idx,i,v){ return _woChoixEcrire('gene',idx,i,v); }
// L'EN-TETE, UNE SEULE FOIS. Rendu par _blocExo, lu par la suite de tests :
// c'est la vraie bande rouge qu'on mesure, pas une copie.
//
// ⚠ EN CARTES, LES COLONNES DISPARAISSENT, ET LEURS NOMS AVEC. « RIR » et
// « Gêne » passent donc dans la bande, chacun avec son ⓘ : sans eux, la
// pastille du lexique n'existerait plus que sur les exercices programmes.
//
// R10 — `sansInfo` : le second bloc d'un superset ne repete pas les ⓘ. Deux
// tableaux a l'ecran, c'etait quatre ⓘ de bande, au-dela du plafond de trois.
function _enteteSeries(large,degressive,sansInfo,parMain){
  const i=k=>sansInfo?'':rcInfo(k);
  if(large){
    return `<th style="color:var(--text);text-align:left;padding-left:10px;font-size:var(--fs-xs);letter-spacing:.5px">`
      +`<div style="display:flex;align-items:center;gap:6px">`
      +`<span style="flex:1;min-width:0">Séries${degressive?' · Dégressive':''}</span>`
      +`<span style="white-space:nowrap">RIR${i('rir')}</span>`
      +`<span style="white-space:nowrap">Gêne${i('douleur')}</span>`
      +`</div></th>`;
  }
  return sansInfo
    ?`<th style="color:var(--text)">Reps</th><th style="color:var(--text)">Charge${uniteCharge(currentUser)==='lb'?'<span class="par-main"> lb</span>':''}${parMain?'<span class="par-main"> /main</span>':''}</th><th style="color:var(--text)">RIR</th><th style="font-size:var(--fs-xs);color:var(--text)">Gêne</th><th style="color:var(--text);font-size:var(--fs-xs)">Validé</th>`
    :`<th style="color:var(--text)">Reps</th><th style="color:var(--text)">Charge${uniteCharge(currentUser)==='lb'?'<span class="par-main"> lb</span>':''}${parMain?'<span class="par-main"> /main</span>':''}</th><th style="color:var(--text)">RIR${rcInfo('rir')}</th><th style="font-size:var(--fs-xs);color:var(--text)">Gêne${rcInfo('douleur')}</th><th style="color:var(--text);font-size:var(--fs-xs)">Validé</th>`;
}
// ══ R10 — LE PLAFOND DE TROIS ⓘ SUR L'ECRAN DE SEANCE ══════════════════
// Un superset rend DEUX tableaux sur le meme ecran. Les ⓘ ne se posent que
// sur le premier : RIR et Gene dans la bande, plus « proposé » ou RPE sur
// une ligne — trois au plus. Le second tableau n'explique rien de nouveau.
// ⚠ PAR DEFAUT, OUI. Sans seance, ou sur un index hors groupe (decors de
// test, reprise), l'exercice se comporte comme un exercice seul.
function _woTeteDeGroupe(idx){
  try{
    const exs=woState&&woState.exercises;
    if(!Array.isArray(exs)||!exs.length) return true;
    const g=_groupesEx(exs).find(x=>x.includes(idx));
    return !g||g[0]===idx;
  }catch(e){ return true; }
}
// R25 — `opts.lignesSeules` : rend le tableau des lignes HTML SANS toucher au
// document. C'est ce que _woMajLignes compare au rendu precedent pour ne
// remplacer que les lignes qui ont change. Le remplissage automatique de la
// charge (plus bas) tourne dans les deux cas, a l'identique.
function renderSets(ex,data,idx,opts){
  const _lignesSeules=!!(opts&&opts.lignesSeules);
  if(idx==null) idx=woState.currentEx;
  const tb=document.getElementById('sets-body-'+idx);if(!tb) return;
  // Cardio : affichage simplifié sans poids ni RIR
  if(isCardio(ex)){
    if(_lignesSeules) return null;
    tb.innerHTML=data.sets.map((s,i)=>{
      const done=s.done;
      return `<tr class="${done?'done':''}">
        <td style="font-weight:700">${i+1}</td>
        <td><button data-arc="off" onclick="toggleSet(${i},${idx})"
          style="width:40px;height:40px;border-radius:var(--r-full);border:2px solid ${done?'var(--text)':'var(--border)'};background:${done?'#1a1a1a':'transparent'};color:var(--sub);font-size:var(--fs-lg);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;padding:0;${done?'box-shadow:0 0 10px rgba(255,255,255,.4)':''}">
          ${done?'<svg viewBox="0 0 24 24" fill="none" stroke="var(--text)" stroke-width="3" stroke-linecap="square" stroke-linejoin="miter" width="19" height="19" style="filter:drop-shadow(0 0 5px rgba(255,255,255,.9))"><polyline points="4.5 12.5 10 18 19.5 7"/></svg>':'○'}
        </button></td>
      </tr>`;
    }).join('');
    _majActionsSeries(ex,data,idx);
    // Vide explicitement : un remplacement peut faire d'un exercice un cardio.
    _majEncartSurcharge(idx);
    return;
  }
  // Plus aucune colonne de cycle ici : l ajustement est porte par la charge
  // suggeree en haut de l exercice, pas par une colonne de tableau.
  const isDeg=data.sets[0]?.degressive||false;
  const enCartes=isDeg||_seriesEnCartes(data);

  const _isCW=isCounterweightEx(ex.name);
  const _parMain=chargeParMain(ex);

  // ── Auto-fill série suivante par paliers fixes ────────────────────
  // RIR 0 → même charge (exacte, sans arrondi) · échec → -1 palier ·
  // RIR n → +n paliers (2,5kg, ou 1,25kg sous 20kg, plafonné à 4).
  // Contrepoids : logique inversée (échec → +assistance, RIR n → -n paliers).
  for(let i=0;i<data.sets.length-1;i++){
    const s=data.sets[i];
    const w=parseFloat(s.weight);
    // SUR UN EXERCICE PROGRAMME, LA CHARGE NE DERIVE PAS. Le coach a fixe un
    // RPE pour toutes les series de la semaine : la faire monter d'un palier
    // parce que la serie precedente etait facile contredirait la consigne
    // qu'on vient d'afficher. Et de toute facon `rir` reste vide ici — c'est
    // le RPE qui est demande, pas le RIR qui est saisi.
    if(s.rpeCible) continue;
    if(w>0 && s.rir!==''&&s.rir!==undefined&&s.rir!==null){
      const _nextBrut=chargeSuivante(w,s.rir,_isCW,1,ex.name);
      const nextW=_nextBrut!=null?plafondDecharge(arrondiSuggestion(_nextBrut,{ex,user:currentUser,depart:w}),w,_isCW,!!(woState&&woState.deload)):null;
      if(!data.sets[i+1].done&&!data.sets[i+1].userEdited){
        data.sets[i+1].weight=nextW;
        data.sets[i+1].isAuto=true;
        delete data.sets[i+1].copieCharge;
      }
    }
    // ⚠ VALIDÉE SANS RIR : LA MÊME CHARGE SUR LA SUIVANTE (30/09/2026). La
    //   série suivante restait vide tant que le RIR n'était pas noté ; celui
    //   qui ne le note pas retapait sa charge à chaque série. Même charge, et
    //   pas de palier : sans RIR, on ne sait pas s'il en restait sous le pied.
    //   copieCharge : ce n'est pas une surcharge (encart et ⓘ ne s'y posent pas).
    else if(w>0&&s.done&&!s.degressive){
      const n=data.sets[i+1];
      if(n&&!n.done&&!n.userEdited){ n.weight=s.weight; n.isAuto=true; n.copieCharge=true; }
    }
  }

  // R14 — LE RIR REDEVIENT UN MENU, avec les memes VALEURS qu'avant R08. Les
  // valeurs et leurs definitions vivent dans RIR_CHOIX (R15), que la liste
  // dessinee lit aussi.
  const RIR_OPTS=RIR_CHOIX.map(c=>c[0]);
  // R08 — L'ECHELLE DE GENE, DITE DANS LA LISTE. Les VALEURS ne changent pas :
  // '1'..'6', comme avant, donc aucune migration et aucun seuil a revoir :
  // DLR_SEANCE_SEUIL lit toujours 4. R16 : valeurs et definitions dans
  // GENE_CHOIX, que la liste dessinee lit aussi.
  const PAIN_OPTS=GENE_CHOIX.map(c=>c[0]);
  // R09 — LE ⓘ DE LA SURCHARGE, UNE FOIS PAR TABLEAU. Il se pose sur la
  // PREMIERE serie qui porte « proposé » — pas sur chaque ligne, ce serait un
  // mur de ⓘ. La serie 1 n'en porte jamais : rien ne la precede pour la
  // proposer. Quand elle est validee, le ⓘ descend sur la suivante.
  // R10 — et seulement sur le premier tableau d'un superset (plafond de trois).
  const _infosIci=_woTeteDeGroupe(idx);
  const _iPremierePropose=(isDeg||!_infosIci)?-1:data.sets.findIndex(_surchargeProposee);
  // R10 — LE ⓘ DU RPE, UNE FOIS PAR TABLEAU. Pose sur chaque ligne verrouillee,
  // il faisait quatre ⓘ pour quatre series, plus les deux de la bande : six a
  // l'ecran, le double du plafond. Il reste sur la premiere.
  const _iPremierRpe=_infosIci?data.sets.findIndex(s=>s&&s.rpeCible):-1;
  // R25 — LA TOUCHE « SUIVANT » DU CLAVIER. Chaque champ de charge porte sa
  // serie (data-serie) et son champ (data-champ) : l'ecouteur delegue du
  // tbody retrouve ainsi le suivant sans lire la mise en page. Le dernier
  // champ OUVERT de l'exercice dit « terminé » (enterkeyhint="done").
  const _iDernierOuvert=data.sets.map(x=>!(x&&x.done)).lastIndexOf(true);
  // R29 — les repetitions precedent la charge dans la ligne : jamais « done ».
  const _eh=(i,champ)=>(champ!=='repsDone'&&i===_iDernierOuvert&&(champ==='weight2'||!isDeg))?'done':'next';
  const _attrs=(i,champ)=>`data-serie="${i}" data-champ="${champ}" enterkeyhint="${_eh(i,champ)}"`;

  // ⚠ L'ÉTIQUETTE « 140×3 » SOUS LE NUMÉRO N'EST PLUS AFFICHÉE (Kevin,
  // 01/10/2026 : « ça perd la personne »). La dernière séance sert toujours :
  // une série vide se valide avec elle (toggleSet), et _woPrecCopier reste.
  const lignes=data.sets.map((s,i)=>{
    const baseW=parseFloat(s.weight)||0;
    const dis=s.done?'disabled':'';
    const rowCls=s.done?'done':'';
    const painAlert=s.pain&&parseInt(s.pain)>=4?' row-alert':'';

    // Les deux charges passent par _woChargeSaisie : le refus du négatif y vit
    // une seule fois, et il est vérifiable.
    const onChW=`_woChargeSaisie(${idx},${i},'weight',this)`;
    const onChW2=`_woChargeSaisie(${idx},${i},'weight2',this)`;
    // La gene : persiste PUIS repeint (R16 : dans _woChoixEcrire). La
    // persistance d'abord : si le rendu venait à échouer, la douleur serait
    // quand même dans l'instantané. Et le rendu appelle _majCarteDouleur en fin
    // de course, ce qui fait apparaître la carte « ça t'a fait mal deux fois »
    // au moment même de la saisie.

    // Weight cell (with « proposé » label)
    //
    // R09 — « AUTO » DEVIENT « proposé ». « AUTO » disait comment la valeur
    // etait arrivee, pas ce qu'on en fait : c'est une proposition, et on la
    // corrige en tapant. En minuscules et en --sub : une indication, pas une
    // alerte.
    // LA BORDURE VERTE RESTE, et sur la meme condition qu'avant : elle dit
    // que la case n'est pas une saisie.
    // ⚠ PAS DE « proposé » SUR UN EXERCICE PROGRAMME. La charge y vient du
    // coach et ne derive pas : _chargeProposee l'exclut.
    const autoLabel=_chargeProposee(s)
      ?`<div class="wo-propose" style="font-size:var(--fs-2xs);color:var(--sub);text-align:center;margin-top:1px;line-height:1.15">proposé${i===_iPremierePropose?rcInfo('surcharge'):''}</div>`:'';
    const weightBorder=s.isAuto&&!s.done?'border-color:var(--green)':'';

    // Wide-mode: content without <td> wrappers (for 2-sub-row card layout)
    const isWide=enCartes;
    const weightInner=isDeg
      ?`<input class="set-input" type="text" inputmode="decimal" autocomplete="off" pattern="[0-9]*[.,]?[0-9]*" ${_attrs(i,'weight')} value="${_poidsSaisie(s.weight)}" placeholder="P1" style="border-color:#9a3412" onchange="${onChW}" ${dis}><input class="set-input" type="text" inputmode="decimal" autocomplete="off" pattern="[0-9]*[.,]?[0-9]*" ${_attrs(i,'weight2')} value="${_poidsSaisie(s.weight2)}" placeholder="P2" style="border-color:#78350f;margin-left:4px" onchange="${onChW2}" ${dis}>`
      :`<div><input class="set-input" type="text" inputmode="decimal" autocomplete="off" pattern="[0-9]*[.,]?[0-9]*" ${_attrs(i,'weight')} style="${weightBorder}" value="${_poidsSaisie(s.weight)}"${_parMain?' placeholder="kg/main" aria-label="Charge par main (kg)"':''} onchange="${onChW}" ${dis}>${autoLabel}</div>`;

    // Simple-mode: <td> wrappers for classic table layout
    const weightCell=isDeg
      ?`<td><input class="set-input" type="text" inputmode="decimal" autocomplete="off" pattern="[0-9]*[.,]?[0-9]*" ${_attrs(i,'weight')} value="${_poidsSaisie(s.weight)}" placeholder="P1" style="border-color:#9a3412" onchange="${onChW}" ${dis}></td><td><input class="set-input" type="text" inputmode="decimal" autocomplete="off" pattern="[0-9]*[.,]?[0-9]*" ${_attrs(i,'weight2')} value="${_poidsSaisie(s.weight2)}" placeholder="P2" style="border-color:#78350f" onchange="${onChW2}" ${dis}></td>`
      :`<td><input class="set-input" type="text" inputmode="decimal" autocomplete="off" pattern="[0-9]*[.,]?[0-9]*" ${_attrs(i,'weight')} style="${weightBorder}" value="${_poidsSaisie(s.weight)}"${_parMain?' placeholder="kg/main" aria-label="Charge par main (kg)"':''} onchange="${onChW}" ${dis}>${autoLabel}</td>`;

    // Cycle cell

    // ── B3.12 — LA CONSIGNE DU COACH, LA OU L'ATHLETE REPOND ──────────
    //
    // Elle s'affichait dans l'EN-TETE de la carte d'exercice — « · RIR 2 » —
    // et nulle part ailleurs. Au moment ou l'athlete choisit sa charge et note
    // son effort, la consigne etait plus haut dans la page, souvent hors
    // ecran : le coach prescrivait une intensite que l'athlete lisait une fois
    // puis oubliait. C'est le maillon 2 de la boucle, et il etait faible.
    //
    // RIEN QUAND IL N'Y A PAS DE CONSIGNE. Une absence de consigne n'est pas
    // une consigne — c'est la regle deja tenue par l'en-tete de la carte.
    //
    // UN RAPPEL, PAS UN JUGEMENT : aucune alerte, aucun blocage, aucune
    // couleur d'erreur. L'ecart se signale en orange quand il depasse un cran
    // — plus loin que ca, ce serait dire a l'athlete qu'il a mal fait, et ce
    // n'est pas a l'app de le dire.
    const _cons=(()=>{ try{ return _rirPrescrit(ex); }catch(e){ return ''; } })();
    const _consRappel=(()=>{
      if(_cons==='') return '';
      // L'ECART SE LIT SUR CE QUI EST DEJA SAISI, et seulement alors : avant
      // de repondre, il n'y a rien a comparer.
      const v=(s.rir===''||s.rir==null)?null:(s.rir==='echec'?0:parseInt(s.rir,10));
      const loin=(v!=null&&isFinite(v)&&Math.abs(v-Number(_cons))>1);
      // « cible » devient « visé » : une cible se rate, un objectif se vise —
      // et le rappel n'est pas un jugement, c'est la regle ecrite juste
      // au-dessus. Le title= reste : il sert au survol, sur bureau.
      //
      // ⚠ PAS DE PASTILLE ICI, ET C'EST UNE MESURE. Elle y a ete posee, puis
      // retiree : a 359 px — la largeur de reference — la cellule debordait de
      // 2 px des que la consigne s'affichait. Deux pixels suffisent a ouvrir
      // un defilement lateral dans un tableau a cinq colonnes, et la regle du
      // lot est explicite : on retire le ⓘ de la CELLULE, on le garde sur
      // l'en-tete de colonne, et on NE REDUIT PAS la police pour le faire
      // tenir. L'explication du RPE reste donc a un doigt — en haut de la
      // meme colonne.
      // R14 — TOUJOURS SOUS LE MENU (display:block). En ligne, il se posait a
      // cote de « 2 » mais passait dessous a cote de « Échec », plus large :
      // deux places differentes dans la meme colonne. Dessous, la colonne RIR
      // est aussi plus etroite, et « Gêne ⓘ » tient sur une ligne.
      return `<span style="display:block;margin-top:1px;line-height:1.15;font-size:var(--fs-2xs);color:${loin?'var(--orange)':'var(--text-faint)'};`
        +`white-space:nowrap;flex:none" title="Intensité demandée par ton coach">visé : ${_cons}</span>`;
    })();
    // ══ LA COLONNE D'INTENSITE : RIR SAISI, OU RPE PRESCRIT ═══════════
    //
    // Demande de Kevin, 27/08/2026 : « sur les tableaux exercices que l'eleve
    // a, la colonne avec les RIR va automatiquement se transformer en RPE. La
    // personne ne pourra pas modifier cette colonne-la. »
    //
    // CE QUE CELA COUTE, ET IL FAUT LE SAVOIR : sur un exercice programme,
    // l'app cesse de recueillir ce que l'athlete a RESSENTI. Elle affiche ce
    // qui a ete DEMANDE. rirMoyenSeance, l'e1RM et l'ecart prescrit/realise
    // n'ont donc plus rien a lire pour cet exercice-la — et c'est PREFERABLE a
    // l'alternative : recopier le RPE prescrit dans `rir` ferait passer une
    // consigne pour une mesure, et le coach lirait sa propre prescription en
    // croyant lire son athlete.
    // « @8 » NE DIT PAS CE QUE C'EST, et son sens vivait dans un title= —
    // donc nulle part, au doigt. Le cadenas dit qu'on ne la regle pas, « RPE »
    // dit de quoi il s'agit, la pastille dit ou aller le lire.
    // ⚠ LE ⓘ EST DEHORS, PAS DEDANS. L'element porte role="img" : tout ce
    // qu'il contient disparait pour un lecteur d'ecran, remplace par son
    // aria-label. Un bouton pose a l'interieur aurait ete inatteignable —
    // visible pour l'oeil, absent pour la voix. Il est donc son VOISIN, ce
    // qui est aussi ce que « a droite » veut dire.
    const rirSelect=s.rpeCible
      ?`<div class="set-input" role="img" aria-label="RPE demandé par ton coach : ${s.rpeCible} sur 10"
          title="Intensité demandée par ton coach : tu ne la règles pas"
          style="padding:4px 4px;font-size:var(--fs-xs);min-width:44px;min-height:38px;display:flex;
            align-items:center;justify-content:center;gap:4px;background:var(--surface-2);color:var(--text-strong);
            border:1px solid var(--border);border-radius:var(--r-1);white-space:nowrap">${icon('lock',10)}RPE ${s.rpeCible}</div>${i===_iPremierRpe?rcInfo('rpe'):''}`
      :(()=>{
        // ══ R14 — LE RIR EN MENU DEROULANT ════════════════════════════════
        // La case montre la valeur courte (« Échec », « 2 », ou « RIR » tant
        // que rien n'est choisi) ; la liste, elle, dit ce que chaque valeur
        // veut dire (R15 : dessinee, voir rirMenuOuvrir).
        //
        // LE `${dis}` RESTE : le RIR se ferme a la validation, il decrit un
        // effort accompli.
        const cur=s.rir==null?'':String(s.rir);
        const _rirVal=RIR_OPTS.indexOf(cur)>=0?cur:'';
        const court=_rirVal==='echec'?'Échec':(_rirVal||'RIR');
        return `<button type="button" class="rir-choix${s.done?' fermee':''}" aria-haspopup="listbox" aria-expanded="false"`
          +` aria-label="RIR de la série ${i+1} : ${_rirVal?court:'non noté'}" onclick="rirMenuOuvrir(${idx},${i},this)" ${dis}>`
          +`<span aria-hidden="true">${court}</span><span class="gene-fl" aria-hidden="true">▾</span></button>${_consRappel}`;
      })();

    // Pain dropdown
    // PAS DE `${dis}` ICI, et c'est le seul champ dans ce cas. Une douleur se
    // déclare souvent une fois la barre reposée : la verrouiller à la
    // validation revenait à ne jamais la recueillir au moment où elle se
    // manifeste. C'est l'intention déjà écrite en fin de renderSets — « la
    // douleur peut aussi être saisie après coup sur une série déjà validée » —
    // que le `disabled` rendait impossible.
    //
    // La charge et le RIR, eux, le gardent : ils décrivent un effort accompli,
    // et les rouvrir permettrait de réécrire une séance validée.
    //
    // R08 — LA CASE N'AFFICHE QUE LE CHIFFRE, LA LISTE DIT CE QU'IL VEUT
    // DIRE : « 6 · je dois arrêter » faisait deborder le tableau.
    // R16 — la liste est celle du RIR (geneMenuOuvrir) : le chiffre en grand,
    // la definition deux fois plus petite. La case est un <button>.
    const _painVal=PAIN_OPTS.indexOf(String(s.pain))>=0?String(s.pain):'';
    const painSelect=`<button type="button" class="gene-choix" aria-haspopup="listbox" aria-expanded="false"`
      +` aria-label="Gêne ressentie sur la série ${i+1} : ${_painVal||'non notée'}" onclick="geneMenuOuvrir(${idx},${i},this)">`
      +`<span aria-hidden="true">${_painVal||'-'}</span><span class="gene-fl" aria-hidden="true">▾</span></button>`;

    // ══ R29 — LES REPETITIONS FAITES, SUR UNE FOURCHETTE SEULEMENT ══════
    // Kevin, 17/09/2026 : « quand la personne met une fourchette de
    // repetitions (et uniquement quand il y en a une), laisse-lui la
    // possibilite de modifier la colonne ». Sur « 8 », la case reste un
    // affichage. Le chiffre va dans `repsDone`, que la performance, le tonnage
    // et le bilan lisent deja en priorite ; vide, on retombe sur la
    // prescription, comme avant. Il se ferme a la validation, comme la charge.
    const _fourch=(!isDeg&&!s.rpeCible)?fourchetteReps(s.reps||ex.reps):null;
    const repsAffiche=(taille)=>_fourch
      ?`<input class="set-input wo-reps" type="number" min="1" max="999" step="1" inputmode="numeric" ${_attrs(i,'repsDone')}`
        +` value="${s.repsDone!=null?s.repsDone:''}" placeholder="${_fourch.min}-${_fourch.max}"`
        +` aria-label="Répétitions faites à la série ${i+1}, fourchette de ${_fourch.min} à ${_fourch.max}" onchange="_woRepsSaisie(${idx},${i},this)" ${dis}>`
      :`<span style="font-family:var(--pile-titre);font-size:${taille}px;font-weight:400;letter-spacing:.5px;line-height:1.2"><span style="font-family:Montserrat,sans-serif;font-size:var(--fs-xs);font-weight:600">×</span>${s.reps||ex.reps}</span>`;

    // Done button
    const doneClr=s.done?'var(--green)':'var(--border)';
    const doneBg=s.done?'var(--green)':'transparent';
    const doneC=s.done?'var(--text)':'var(--sub)';

    // Wide layout: 2-sub-row card (no horizontal scroll)
    //
    // R14 — SEULE LA SERIE DEGRESSIVE Y PASSE, et la carte retrouve sa forme
    // d'avant R08 : numero et deux charges en haut ; RIR, gene et validation
    // en bas. Le numero garde le badge RECORD, que la disposition a cinq
    // colonnes affiche aussi.
    if(isWide){
      const highPain=s.pain&&parseInt(s.pain)>=4;
      const cardBg=highPain?'var(--danger-bg)':s.done?'#E0202015':'var(--surface-1)';
      const cardBorder=highPain?'var(--red)':s.done?'var(--red)':'var(--border)';
      return `<tr class="${rowCls}">
        <td style="padding:4px 8px">
          <div style="background:${cardBg};border:1px solid ${cardBorder};border-radius:var(--r-2);padding:8px 10px">
            <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
              <div style="text-align:center;min-width:28px;flex-shrink:0">
                <div style="font-size:var(--fs-xs);font-weight:800;color:var(--red-text);line-height:1">${i+1}${_eclairObjectif(idx,i)}${_badgeRecord(idx,i)}${_badgeVideoSerie(s)}</div>
                <div>${repsAffiche(18)}</div>
              </div>
              ${weightInner}
            </div>
            <div class="wo-intensite" style="display:flex;align-items:center;flex-wrap:wrap;gap:6px 8px">
              ${rirSelect}
              ${painSelect}
              <button class="hit44" data-arc="off" onclick="toggleSet(${i},${idx})" style="margin-left:auto;width:34px;height:34px;border-radius:var(--r-full);border:2px solid ${s.done?'var(--text)':'var(--border)'};background:${s.done?'#1a1a1a':'transparent'};color:var(--sub);cursor:pointer;font-size:var(--fs-md);display:inline-flex;align-items:center;justify-content:center;padding:0;${s.done?'box-shadow:0 0 10px rgba(255,255,255,.4)':''}">${s.done?'<svg viewBox="0 0 24 24" fill="none" stroke="var(--text)" stroke-width="3" stroke-linecap="square" stroke-linejoin="miter" width="17" height="17" style="filter:drop-shadow(0 0 5px rgba(255,255,255,.9))"><polyline points="4.5 12.5 10 18 19.5 7"/></svg>':'○'}</button>
            </div>
          </div>
        </td>
      </tr>`;
    }
    return `<tr class="${rowCls}${painAlert}">
      <td style="text-align:center;padding:${_fourch?'4px 1px':'4px 6px'}">
        <span style="display:block;font-size:var(--fs-xs);font-weight:800;color:var(--red-text);line-height:1">${i+1}${_eclairObjectif(idx,i)}${_badgeRecord(idx,i)}${_badgeVideoSerie(s)}</span>
        ${repsAffiche(20)}
      </td>
      ${weightCell}
      <td class="wo-intensite">${rirSelect}</td>
      <td>${painSelect}</td>
      <td><button class="hit44" data-arc="off" onclick="toggleSet(${i},${idx})" style="width:34px;height:34px;border-radius:var(--r-full);border:2px solid ${s.done?'var(--text)':'var(--border)'};background:${s.done?'#1a1a1a':'transparent'};color:var(--sub);cursor:pointer;font-size:var(--fs-md);display:inline-flex;align-items:center;justify-content:center;padding:0;${s.done?'box-shadow:0 0 10px rgba(255,255,255,.4)':''}">${s.done?'<svg viewBox="0 0 24 24" fill="none" stroke="var(--text)" stroke-width="3" stroke-linecap="square" stroke-linejoin="miter" width="17" height="17" style="filter:drop-shadow(0 0 5px rgba(255,255,255,.9))"><polyline points="4.5 12.5 10 18 19.5 7"/></svg>':'○'}</button></td>
    </tr>`;
  });
  if(_lignesSeules) return lignes;
  tb.innerHTML=lignes.join('');
  // R25 — ce qui vient d'etre rendu, pour que la prochaine saisie de charge
  // ne remplace que ce qui change ; et l'ecouteur de la touche « Suivant ».
  _woLignesRendues.set(tb,lignes);
  _woBrancherEnchainement(tb,idx);
  // Le « − » n'existe que tant que la dernière série n'est pas validée : sa
  // présence dépend donc du tableau qui vient d'être repeint.
  _majActionsSeries(ex,data,idx);
  try{ _majBandeTempo(ex,data,idx); }catch(e){}
  // Deux séries validées à 4 ou plus sur CET exercice : la carte apparaît.
  // Ici et pas dans toggleSet, parce que la douleur peut aussi être saisie
  // après coup sur une série déjà validée.
  _majCarteDouleur(idx);
  // R09 — la premiere charge proposee de la seance se presente, une fois.
  _majEncartSurcharge(idx);
}
// ══ R09 — LA CHARGE PROPOSEE, ET LA PREMIERE FOIS QU'ON LA VOIT ══════════
//
// PURE. Une charge que RepCore PROPOSE : posee par le remplissage automatique
// (isAuto), pas encore validee — et hors des deux cas ou « proposé »
// mentirait :
// - une serie programmee (rpeCible) : la charge y vient du coach, elle ne
//   derive pas, et isAuto n'y dit que « pre-remplie » ;
// - une serie degressive : son tableau n'a aucune mention sous P1 / P2.
// Elle ne lit que les drapeaux, et n'en change aucun.
function _chargeProposee(s){
  return !!(s&&s.isAuto&&!s.done&&!s.rpeCible&&!s.degressive);
}
// Une charge proposée PAR LA SURCHARGE : ni la suggestion posée sur la série 1
// (sugPremiere), ni la copie d'une série validée sans RIR (copieCharge).
function _surchargeProposee(s){
  return _chargeProposee(s)&&!s.sugPremiere&&!s.copieCharge;
}
const SURCHARGE_ENCART_TITRE='Ta charge monte toute seule';
const SURCHARGE_ENCART_TEXTE='RepCore augmente ta charge quand tu gardes des '
  +'répétitions en réserve. C\'est la surcharge progressive. Tu peux toujours '
  +'la corriger : tape simplement une autre valeur.';
// PURE. L'encart, ou rien.
//
// DEUX DRAPEAUX, ET IL FAUT LES DEUX.
// - currentUser.vus.surcharge, PERSISTANT : pose par « J'ai compris », et
//   par lui seul. Un utilisateur existant n'a pas le champ — il voit l'encart
//   une fois, puis plus jamais. Aucune migration.
// - woState._surchargeVue, LOCAL A LA SEANCE : la cle de l'exercice qui a pris
//   l'encart. Sans lui, les quatre exercices de la seance le montreraient tour
//   a tour. La cle et non l'index : un remplacement en cours de seance decale
//   les index (meme choix que la carte de douleur).
function _htmlEncartSurcharge(idx){
  const u=currentUser;
  if(!u||(u.vus&&u.vus.surcharge===true)) return '';
  const ex=((woState&&woState.exercises)||[])[idx];
  if(!ex||isCardio(ex)) return '';
  const k=exKey(ex.name);
  if(!k) return '';
  const pris=woState._surchargeVue;
  if(pris&&pris!==k) return '';
  // Pas encore pris : il faut qu'une charge soit REELLEMENT proposee ici.
  if(!pris){
    const d=woState.sessionData&&woState.sessionData[idx];
    if(!d||!Array.isArray(d.sets)||!d.sets.some(_surchargeProposee)) return '';
  }
  return `<div class="wo-surcharge" style="background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-3);padding:14px 14px;margin-top:10px">
    <div style="font-size:var(--fs-sm);font-weight:800;color:var(--text);line-height:1.4;margin-bottom:6px">${escapeHtml(SURCHARGE_ENCART_TITRE)}</div>
    <div style="font-size:var(--fs-sm);color:var(--text);line-height:1.75">${escapeHtml(SURCHARGE_ENCART_TEXTE)}</div>
    <button onclick="accuserEncartSurcharge()" class="btn btn-outline btn-sm" style="width:100%;margin:10px 0 0;font-size:var(--fs-2xs);letter-spacing:1px">J'ai compris</button>
  </div>`;
}
// Repeint la seule zone de l'encart. C'est ICI que l'exercice prend l'encart
// pour la seance : au moment ou il s'affiche pour la premiere fois.
// ⚠ LE RENDU N'ECRIT RIEN DANS LE DOSSIER. woState est la seance, pas le
// dossier ; currentUser.vus ne s'ecrit que sur le geste.
function _majEncartSurcharge(idx){
  const z=document.getElementById('wo-surcharge-'+idx);
  if(!z) return;
  const h=_htmlEncartSurcharge(idx);
  if(h&&woState&&!woState._surchargeVue)
    woState._surchargeVue=exKey(woState.exercises[idx].name);
  z.innerHTML=h;
}
// Le drapeau est pose par un GESTE, jamais par le rendu — meme doctrine que
// accuserEncartOsseux.
function accuserEncartSurcharge(){
  if(!currentUser) return false;
  if(!currentUser.vus||typeof currentUser.vus!=='object') currentUser.vus={};
  currentUser.vus.surcharge=true;
  saveUser();
  document.querySelectorAll('[id^="wo-surcharge-"]').forEach(z=>{ z.innerHTML=''; });
  return true;
}
// ══════════════ DOULEUR RÉPÉTÉE DANS LA SÉANCE EN COURS ════════════════════
// Détection PURE et LOCALE : on compte les séries VALIDÉES de CE seul exercice,
// dans CETTE seule séance. Rien n'est lu dans l'historique, rien n'y est écrit.
//
// Ce circuit ne touche à AUCUN des signaux du coach : signauxEntrainement,
// urgencyScore et les seuils SIG_* sont inchangés. Le signal « douleur sur deux
// séances » continue de vivre sa vie, sur sa fenêtre à lui. Ici on parle à
// l'athlète, tout de suite, pendant qu'il a la barre en main — ce n'est ni la
// même question ni le même destinataire.
const DLR_SEANCE_SEUIL=4;      // même échelle que la colonne « Douleur » (1..6)
const DLR_SEANCE_MIN=2;        // deux séries validées suffisent
const DLR_ALLEGE=0.80;         // « J'allège » : −20 %
function seriesDouloureusesSeance(idx){
  const d=woState&&woState.sessionData&&woState.sessionData[idx];
  if(!d||!Array.isArray(d.sets)) return 0;
  let n=0;
  for(const s of d.sets){
    if(!s||s.done!==true) continue;
    if(parseInt(s.pain,10)>=DLR_SEANCE_SEUIL) n++;
  }
  return n;
}
// Le choix est retenu PAR EXERCICE et PAR SÉANCE. Par exercice : la clé est
// exKey, pas l'index — un remplacement en cours de séance décale les index.
// Par séance : woState meurt avec elle, il n'y a rien à purger.
function _dlrCle(idx){
  const ex=(woState&&woState.exercises||[])[idx];
  return ex&&ex.name?exKey(ex.name):'';
}
function _dlrChoixFait(idx){
  const k=_dlrCle(idx);
  return k?((woState&&woState.douleurChoix)||{})[k]||'':'';
}
function _htmlCarteDouleur(idx){
  // Un drapeau rouge déjà posé prime, et reste SEUL à l'écran. Proposer
  // « j'allège » à quelqu'un qui a décrit une douleur irradiante reviendrait à
  // l'aider à continuer — c'est exactement ce que l'écran d'arrêt refuse.
  if(drapeauQuelconqueActif(currentUser)) return '';
  const ex=(woState&&woState.exercises||[])[idx];
  if(!ex||isCardio(ex)) return '';
  const choix=_dlrChoixFait(idx);
  if(choix==='continue'||choix==='declare') return '';
  if(choix==='allege'){
    return `<div style="background:var(--surface-2);border-radius:var(--r-3);padding:12px 14px;margin-top:10px;font-size:var(--fs-sm);color:var(--text-strong);line-height:1.6">J'ai baissé tes séries qui restent de 20 %. À toi de voir si ça passe mieux.</div>`;
  }
  if(seriesDouloureusesSeance(idx)<DLR_SEANCE_MIN) return '';
  return `<div style="background:var(--warning-bg);border:1px solid var(--warning-border);border-radius:var(--r-3);padding:12px 14px;margin-top:10px">
    <div style="font-size:var(--fs-sm);color:var(--text);line-height:1.6;margin-bottom:10px">Ça t'a fait mal deux fois sur cet exercice. Qu'est-ce que tu veux faire ?</div>
    <div style="display:flex;flex-direction:column;gap:6px">
      <button class="btn btn-outline btn-sm dlr-btn" data-choix="continue" data-idx="${idx}" style="width:100%;margin:0;letter-spacing:1px;font-size:var(--fs-2xs)">Je continue comme ça</button>
      <button class="btn btn-outline btn-sm dlr-btn" data-choix="allege" data-idx="${idx}" style="width:100%;margin:0;letter-spacing:1px;font-size:var(--fs-2xs)">J'allège</button>
      <button class="btn btn-outline btn-sm dlr-btn" data-choix="declare" data-idx="${idx}" style="width:100%;margin:0;letter-spacing:1px;font-size:var(--fs-2xs)">Je déclare une gêne</button>
    </div>
  </div>`;
}
// Repeinte la seule zone de la carte, et recâble ses boutons. Ne repasse pas
// par renderWoEx : celui-ci reconstruit le tableau des séries, et une saisie
// en cours de frappe y serait perdue.
function _majCarteDouleur(idx){
  const z=document.getElementById('wo-douleur-'+idx);
  if(!z) return;
  z.innerHTML=_htmlCarteDouleur(idx);
  z.querySelectorAll('.dlr-btn').forEach(b=>{
    const c=b.getAttribute('data-choix');
    b.onclick=()=>_dlrChoisir(idx,c);
  });
}
function _dlrPoserChoix(idx,choix){
  const k=_dlrCle(idx);
  if(!k||!woState) return;
  if(!woState.douleurChoix) woState.douleurChoix={};
  woState.douleurChoix[k]=choix;
  woPersist();
}
function _dlrChoisir(idx,choix){
  if(choix==='continue'){ _dlrPoserChoix(idx,'continue'); _majCarteDouleur(idx); return; }
  if(choix==='allege'){ _dlrAlleger(idx); return; }
  if(choix==='declare'){ _dlrDeclarer(idx); return; }
}
// −20 % sur les séries NON VALIDÉES uniquement. Une série déjà validée est un
// fait : la réécrire falsifierait la séance.
// userEdited est posé en même temps, sinon le remplissage automatique de
// renderSets reprendrait la main à la ligne suivante et remonterait la charge.
function _dlrAlleger(idx){
  const d=woState&&woState.sessionData&&woState.sessionData[idx];
  if(!d||!Array.isArray(d.sets)) return;
  for(const s of d.sets){
    if(!s||s.done===true) continue;
    const w=parseFloat(s.weight);
    if(!(w>0)) continue;
    s.weight=arrondiCharge125(w*DLR_ALLEGE,w);
    s.userEdited=true;
    s.isAuto=false;
  }
  _dlrPoserChoix(idx,'allege');
  renderSets((woState.exercises||[])[idx],d,idx);
  _majCarteDouleur(idx);
}
// Le formulaire de contrainte EXISTANT, celui du bilan et de la fiche coach.
// Pré-rempli sur l'EXERCICE et non sur une zone : seul l'athlète sait où ça
// fait mal, et déduire une articulation d'un mouvement reviendrait à décider
// à sa place.
function _dlrDeclarer(idx){
  const ex=(woState&&woState.exercises||[])[idx];
  if(!ex) return;
  _dlrPoserChoix(idx,'declare');
  _majCarteDouleur(idx);
  ouvrirFormContrainte('','moi');
  _ctSaisie.libelle='Ressenti pendant : '+ex.name;
  _ctRepeindre();
}

// Fragment de phrase optionnel : « Poids: 82kg » ou rien du tout. Sert aux
// textes courants, JAMAIS aux cases à remplir — celles-ci gardent leur tiret,
// qui y signifie « en attente d'une valeur ».
function _fragmentSiValeur(prefixe,val,suffixe){
  if(val==null||val===''||val==='—'||val==='-'||(typeof val==='number'&&!isFinite(val))) return '';
  return (prefixe||'')+val+(suffixe||'');
}
// Récupère la dernière charge enregistrée à RIR 0 pour un exercice
// ── Historique : ne comparer que ce qui est comparable ──────────────────────
// Un même exercice peut figurer dans deux séances de la semaine avec des
// fourchettes de répétitions différentes — « abdos poulie » en 8-10 le lundi,
// en 15-20 le samedi. Chercher la dernière charge par le seul NOM d'exercice
// proposait donc le lundi le poids du samedi, qui ne veut rien dire à ce
// nombre de répétitions.
// Rattachement, dans cet ordre :
//   1. le CRÉNEAU (slot 0..6, lundi..dimanche), enregistré depuis cette version ;
//   2. à défaut le NOM de la séance — tout l'historique antérieur n'a que ça,
//      et sans ce repli l'app repartirait de zéro sur chaque exercice ;
//   3. sinon rien. Pas de repli global : ce serait exactement le bug d'origine.
// ── Jointure de l'historique par identité, et non par égalité de chaîne ─────
// sessions[n].data reste indexé par le NOM EN CLAIR : on ne le réécrit pas, on
// construit un index { exKey → clé réelle } au-dessus. Renommer « DÉVELOPPÉ
// COUCHÉ » en « DEVELOPPE COUCHE » ne coupe donc plus la suggestion de charge.
//
// Mémoïsé par séance, car ces fonctions remontent tout l'historique à chaque
// affichage d'exercice : sans cache, un athlète à 200 séances reconstruirait
// 200 index à chaque changement d'exercice pendant sa séance.
//
// Le cache est indexé sur l'OBJET data lui-même, pas sur sess.id. Une première
// version utilisait l'identifiant : deux séances portant le même id — deux
// comptes ouverts l'un après l'autre, un jeu d'essai, un import — se
// partageaient alors la même entrée, et la seconde recevait l'index de la
// première. La conséquence n'était pas une erreur visible mais une charge
// suggérée prise sur le mauvais exercice, ce qui est pire.
// L'identité d'objet ne peut pas entrer en collision, se passe de champ id
// (les séances anciennes n'en ont pas) et se libère toute seule.
// Les clés de l'index sont CANONICALISÉES, c'est-à-dire passées par les alias.
// Un alias va de l'ancien nom vers le nouveau ; l'historique, lui, ne contient
// que des anciens noms. Indexer sur la clé brute et chercher avec le nouveau
// nom ne se rencontrait donc jamais, et la fusion ne rendait aucune charge.
// En canonicalisant les deux côtés, l'ancien et le nouveau se rejoignent.
// Le compteur de génération invalide les index dès qu'un alias est ajouté :
// sans lui, une fusion ne prendrait effet qu'au prochain rechargement.
let _aliasGen=0;
const _idxSessData=new WeakMap();
function _indexSessionData(sess){
  if(!sess||!sess.data) return null;
  const cache=_idxSessData.get(sess.data);
  if(cache&&cache.gen===_aliasGen) return cache.idx;
  const idx={};
  for(const nom of Object.keys(sess.data)){
    const k=resoudreAlias(exKey(nom));
    // Première clé gagnante : si deux noms se normalisent pareil dans la même
    // séance, on garde le premier plutôt que d'en perdre un silencieusement.
    if(k&&idx[k]===undefined) idx[k]=nom;
  }
  _idxSessData.set(sess.data,{gen:_aliasGen,idx});
  return idx;
}
// Retrouve l'entrée d'un exercice dans une séance, par identité normalisée.
function _dataDeSeance(sess,nomEx){
  if(!sess||!sess.data) return null;
  const direct=sess.data[nomEx];
  if(direct) return direct;                 // chemin rapide : nom identique
  const idx=_indexSessionData(sess); if(!idx) return null;
  const reel=idx[resoudreAlias(exKey(nomEx))];
  return reel!=null?sess.data[reel]:null;
}
function _memeCreneau(sess,slot,progName){
  if(!sess) return false;
  if(slot!=null&&sess.slot!=null) return sess.slot===slot;
  if(progName&&sess.name) return sess.name===progName;
  return false;
}
function getLastZeroRIRWeight(exName,slot,progName){
  if(!currentUser.sessions?.length) return null;
  for(let i=currentUser.sessions.length-1;i>=0;i--){
    const sess=currentUser.sessions[i];if(!sess.data) continue;
    if(!_memeCreneau(sess,slot,progName)) continue;
    const d=_dataDeSeance(sess,exName);if(!d) continue;
    const zeroSets=d.sets?.filter(s=>s.done&&(s.rir==='0'||s.rir===0)&&s.weight);
    if(zeroSets?.length) return parseFloat(zeroSets[zeroSets.length-1].weight);
  }return null;
}
function toggleSet(i,idx){
  // idx explicite : sur un superset, le bouton « validé » du second exercice
  // ne doit pas cocher une série du premier.
  if(idx==null) idx=woState.currentEx;
  const d=woState.sessionData[idx];if(!d) return;
  const avant=!!d.sets[i].done;
  // ⚠ VALIDER SANS CHARGE, AVEC UNE VALEUR À REPRENDRE (30/09/2026). Une
  //   charge proposée (isAuto) est déjà dans la case et reste telle quelle.
  //   Case vide : la même série de la dernière séance, si elle existe. Sans
  //   aucune valeur, rien ne change — la série se valide vide, comme avant.
  if(!avant){
    const s=d.sets[i], ex=(woState.exercises||[])[idx];
    if(s&&ex&&!isCardio(ex)&&!s.degressive&&!(parseFloat(s.weight)>0)){
      const p=prevSeries(ex.name,woState.slot,woState.progName)[i];
      if(p){ _woPrecAppliquer(ex,s,p); s.isAuto=true; }
    }
  }
  d.sets[i].done=!avant;
  // Décocher ne lance rien et n'annule rien : c'est une correction de saisie,
  // pas un événement d'entraînement.
  if(!avant){
    // LE GESTE QUI PRÉCÈDE IMMÉDIATEMENT LE REPOS. L'interrupteur du son a pu
    // être activé lors d'une séance précédente : le dossier dit « activé »,
    // mais aucun geste de CETTE page n'a encore ouvert de contexte, et le bip
    // qui va suivre serait muet sur iOS. Une seule fois, la première série
    // validée suffit à couvrir toute la séance.
    //
    // Rien quand le son est éteint : on n'ouvre pas de contexte audio pour
    // quelqu'un qui a demandé le silence.
    if(currentUser&&currentUser.sonRepos&&!_ctxSon) _amorcerSon();
    // Le record se juge à la validation, contre les séances PASSÉES. Décocher
    // ne l'efface pas : c'est une correction de saisie, pas un événement.
    _marquerRecordSiBesoin(idx,i);
    const now=Date.now();
    d.sets[i].reposReel=_reposReelDepuis(d,i,now);
    d.sets[i].tValid=now;
    const sec=_reposApresSerie(idx,i);
    if(sec) demarrerRepos(sec,(woState.exercises[idx]||{}).name||'');
  }
  renderSets(woState.exercises[idx],d,idx);
  try{ woMajCompteurSeries(); }catch(e){}
  // APRÈS renderSets, jamais avant : la ligne que l'arc doit traverser vient
  // d'être détruite et reconstruite, et l'animation doit viser la NOUVELLE.
  // Et seulement quand on coche : décocher est une correction de saisie, pas
  // un événement d'entraînement — rien ne doit le célébrer.
  if(!avant) _arcSerieValidee(idx,i);
  // Le RIR en un toucher, pendant 4 s ; décocher la referme.
  try{ if(!avant) _rirBandeOuvrir(idx,i); else _rirBandeFermer(); }catch(e){}
  woPersist();
}
// ── ANIMATION 3 : LA VALIDATION DE SÉRIE — l'élément signature ─────────────
// Le geste répété 25 à 40 fois par séance, et le seul endroit du système où
// l'on a le droit d'être spectaculaire. Tout le reste reste discipliné pour
// que ce moment-là ressorte.
//
// L'ORDRE EST LE PROPOS. L'arc part du doigt, traverse la ligne de gauche à
// droite en 140 ms, le numéro de série encaisse l'impact, la rémanence cyan
// s'éteint en 380 ms. L'haptique lourde tombe SUR la décharge et pas à
// l'appui : à l'appui elle accuserait réception, sur la décharge elle libère.
//
// NE LÈVE JAMAIS. Une série validée doit l'être même si l'animation échoue :
// l'écriture a déjà eu lieu chez l'appelant, et rien ici ne doit pouvoir la
// rendre douteuse. C'est la règle 7 poussée jusqu'au bout — l'animation cède,
// toujours, et en silence.
function _arcSerieValidee(idx,i){
  try{
    // LE RECORD EST LU UNE FOIS, EN TETE : les cinq gestes qui suivent doivent
    // raconter la meme chose, et relire le Set a chaque appel les exposerait a
    // diverger si le marquage changeait entre-temps.
    const rec=_recordsVus.has(idx+':'+i);
    // LA FOUDRE, UNE FOIS PAR RECORD. Décocher puis recocher la même série ne
    // la rejoue pas : c'est une correction de saisie, pas un second record.
    // Elle porte sa propre vibration — « succes » par-dessus la brouillerait.
    const foudre=rec&&!_foudresJouees.has(idx+':'+i);
    if(foudre){ _foudresJouees.add(idx+':'+i); _foudreSurCharge(idx,i); }
    else arcHaptique(rec?'succes':'lourde');
    const tb=document.getElementById('sets-body-'+idx);
    if(!tb) return;
    const ligne=tb.children[i];
    if(!ligne) return;
    // Le point de contact s'il est frais, sinon rien : mieux vaut un arc sans
    // étincelle de départ qu'une étincelle au mauvais endroit.
    const p=arcDernierPoint();
    if(p) arcFlash(p,{couleur:rec?'var(--arc-peak)':'var(--arc-current)',taille:rec?76:56});
    arcTraversee(ligne,rec?{couleur:'var(--arc-peak)',duree:ARC.release}:undefined);
    arcGlow(ligne,rec?{couleur:'rgba(255,46,147,.55)'}:undefined);
    // « Le compteur encaisse l'impact » : le numéro de série, première cellule
    // de la ligne. C'est lui qui compte, et c'est vers lui que l'œil revient.
    // Pas de flash ni de halo dessus — l'arc vient de passer, en rajouter
    // brouillerait le seul moment fort de la séance.
    // LA COCHE SE TRACE, de sa pointe a sa branche longue, dans le sillage de
    // l'arc. Un seul <polyline> de 17x17 px : stroke-dashoffset est ici un cout
    // borne et c'est la seule propriete qui rende un trace — meme exception que
    // svg.arc-courbe. Le nettoyage du strokeDasharray a la fin est obligatoire :
    // sans lui la coche resterait pointillee le jour ou quelqu'un change le trace.
    // La garde !arcReduit() ne peut PAS etre remplacee par une regle CSS
    // animation:none — la coche resterait figee a strokeDashoffset:L, invisible.
    const coche=ligne.querySelector('button[data-arc="off"] polyline');
    if(coche&&coche.getTotalLength&&coche.animate&&!arcReduit()){
      let L=0; try{ L=coche.getTotalLength(); }catch(e){}
      if(L>0){
        coche.style.strokeDasharray=L;
        const ac=_animer(coche,[{strokeDashoffset:L},{strokeDashoffset:0}],
          {duration:160,easing:ARC.discharge,fill:'none'});
        const net=()=>{ try{ coche.style.strokeDasharray=''; }catch(e){} };
        if(ac){ ac.addEventListener('finish',net); ac.addEventListener('cancel',net); }
        else net();
      }
    }
    // LE MOT RECORD SE POSE AU LIEU D'ETRE DEJA LA. toggleSet appelle
    // renderSets PUIS _arcSerieValidee : le badge est donc deja ecrit dans la
    // ligne neuve quand l'arc magenta commence a la traverser — le verdict
    // s'affichait avant l'evenement qui le produit. Il demarre a t=140 ms,
    // quand l'arc a fini de traverser.
    // fill:'backwards' et non 'both' : invisible pendant le delai, mais il
    // reprend son style de feuille a la fin — un forwards figerait un transform
    // sur un noeud que le prochain renderSets detruira.
    if(rec&&!arcReduit()){
      const b=ligne.querySelector('[title="Nouveau record"]');
      if(b&&b.animate) _animer(b,
        [{transform:'scale(.4)',opacity:0},
         {transform:'scale(1.14)',opacity:1,offset:.62},
         {transform:'scale(1)',opacity:1}],
        {duration:ARC.release,delay:ARC.strike,easing:'cubic-bezier(.2,1.5,.4,1)',fill:'backwards'});
    }
    const compteur=ligne.firstElementChild;
    if(compteur) arcDecharge(compteur,{flash:false,halo:false,impact:rec?1.22:undefined});
  }catch(e){}
}
// La charge de la série qui vient de battre le record, frappée par la foudre.
// L'« ancienne » valeur est le meilleur de l'historique ET des records déjà
// battus plus tôt dans cette séance : le troisième record de la soirée compte
// depuis le deuxième, pas depuis celui de la semaine dernière.
function _foudreSurCharge(idx,i){
  try{
    const ex=(woState.exercises||[])[idx];
    const d=woState.sessionData[idx];
    if(!ex||!d||!d.sets[i]) return;
    const champ=document.querySelector('#sets-body-'+idx+' input[data-serie="'+i+'"][data-champ="weight"]');
    if(!champ) return;
    let anc=0;
    const r=recordsExercice(currentUser,ex.name);
    if(r&&r.meilleureCharge) anc=r.meilleureCharge.kg||0;
    d.sets.forEach((s,j)=>{
      if(j!==i&&s&&s.done&&_recordsVus.has(idx+':'+j)) anc=Math.max(anc,parseFloat(s.weight)||0);
    });
    rcFoudreRecord(champ,anc||null,d.sets[i].weight);
  }catch(e){}
}
